'use client';

// =============================================================================
// PlanBoard — adapter del board /plan para el super-admin (Supabase, mig 0093)
// =============================================================================
// PROYECTOS FINITOS + tareas, priorizados por el Perro Guardián con la lente
// DINERO-RÁPIDO-FÁCIL: cada item tiene IMPACTO y ESFUERZO (1-100), un SCORE que los
// combina (1-100, comparado contra todo el resto) y una RAZÓN que lo explica. Las
// tareas pueden vivir en varios proyectos. Toda la UI vive en board/BoardShell.

import { useEffect, useState } from 'react';
import { BoardShell } from './board/BoardShell';
import { useBoard } from './board/useBoard';
import { repoPlan, apiPlan } from './board/repo-plan';
import { type BoardTask, type Label, type Repo, type BoardUser, type Hist, type Prio, type Fuente, type Actor, type GuardPatch, type GuardProjPatch, type GuardResult, prioFromScore, clampScore, pidDe, HIST_CAP, scoreFromPrio, uid } from './board/types';
import { CATALOGO_PROYECTOS } from '@/lib/plan-proyectos-catalogo';

const K9 = 'mako_plan_v9', K_PROJS = 'mako_plan_projs_v7';
const SEED_TS = Date.parse('2026-07-13T12:00:00Z');

// REGLA: toda tarjeta que crea MaKo deja rastro de QUÉ hizo y CUÁNDO. El historial
// de las tandas del 16/7 no puede decir SEED_TS (13/7) ni el genérico "Creó la
// tarjeta": mentiría sobre la fecha y no diría de dónde salió. Ese rastro es lo
// único que hace auditable un board donde la IA escribe.
const CARGA_16J = Date.parse('2026-07-16T18:00:00Z');
const CARGA_17J = Date.parse('2026-07-17T17:30:00Z'); // reconciliación del board con el trabajo hecho
const HIST_DICTADAS = 'Creó la tarjeta — de las 7 grandes tareas que dictaste el 16/7';
const HIST_AUDITORIA = 'Creó la tarjeta — hallazgo de la auditoría del 16/7';
// 175-184: trabajo real del 16-17/7 que no tenía tarjeta. Se cardó el 17/7 al cruzar
// los commits contra el board (verificado tarea por tarea, adversarialmente).
const HIST_RECONCILE = 'Creó la tarjeta — trabajo del 16-17/7 que no tenía tarjeta; Claude Code lo cardó al reconciliar el board';
// Las dos tandas del 16/7: 132-161 las dictó Martín; 162-173 salieron de la auditoría.
const histDeCarga = (num: number): { ts: number; text: string } | null =>
  num >= 132 && num <= 161 ? { ts: CARGA_16J, text: HIST_DICTADAS }
    : num >= 162 && num <= 173 ? { ts: CARGA_16J, text: HIST_AUDITORIA }
    : num >= 175 && num <= 184 ? { ts: CARGA_17J, text: HIST_RECONCILE }
      : null;

const P = (id: string, emoji: string, name: string, color: string, score: number, impacto: number, esfuerzo: number, scoreRazon: string, detalle: string, deadline: string, hist?: { ts: number; text: string }): Label =>
  ({ id, emoji, name, color, score, impacto, esfuerzo, scoreRazon: scoreRazon || undefined, deadline: deadline || undefined, detalle, historial: [{ id: 'seedp' + id, ts: hist?.ts ?? SEED_TS, actor: 'code', text: hist?.text ?? 'Creó el proyecto' }] });

// ── Proyectos FINITOS (score 1-100 + impacto/esfuerzo + razón comparada) ──
const PROJS_DEFAULT: Label[] = [
  P("oferta-cebolla", "🧅", "Oferta CEBOLLA: vender por capas y que entren clientes ya", "#D0504A", 99, 96, 30, "Es el ÚNICO bloque con fecha dura: Leila y Leandro entran el viernes 17/7. Todo lo demás puede esperar un día más sin que pase nada; esto no. Y arriba del go-live porque es el go-live, pero con fecha y con nombre y apellido.", "La oferta se vende por capas, como una cebolla: cada tipo de cliente entra por la capa que le corresponde y desbloquea más a medida que avanza. Este proyecto define QUÉ capa se vende hoy y cuál queda para después, deja que un usuario entre como cliente de otra oferta distinta, y piensa el arranque de cada tipo de cliente. La primera decisión (qué capa es para YA) no es código: son 30 minutos de definición que determinan si el resto del trabajo son 4 horas o 4 días. Está listo cuando Leila y Leandro entran, ven su capa y no ven nada de lo que no compraron.", "2026-07-17", { ts: CARGA_16J, text: "Creó el proyecto — Oferta CEBOLLA, del 16/7. Score 99: único bloque con fecha dura (Leila y Leandro, viernes 17/7)" }),
  P("golive-encender-el", "🚀", "Prender el producto para el primer cliente real", "#D0504A", 98, 98, 45, "Es EL norte: pasar de 'está el código en simulado' a un cliente piloto facturando de verdad. Todo lo demás ya construido no vale un peso hasta que esto se prende, por eso va arriba de todo aunque tenga más esfuerzo que la landing.", "El salto de 'está el código' a 'el producto actúa': hoy todo corre en simulación y nada sale de verdad. Este proyecto prende, de a uno y con cuidado, lo que ya está construido pero apagado (nutrición, email, WhatsApp oficial y no oficial, CRM automático), cliente por cliente, sin molestar a los demás ni perder datos de Meta que no se recuperan. Está listo cuando un cliente piloto corre con envío real encendido, dominio de email verificado, WhatsApp conectado y una plantilla aprobada por Meta en vivo.", "2026-07-31"),
  P("landing-de-venta", "🌐", "Landing /vsl + páginas de detalle + atribución del VSL", "#2F6FED", 95, 92, 25, "Es literalmente cómo se vende y se mide el tráfico, y el grueso ya está arriba: el cuello es que Martín pegue el código y arme el WhatsApp. Impacto directo sobre la venta con esfuerzo bajísimo, el quick win más claro después del go-live.", "La cara pública de venta de MaKo: la landing con el VSL en el hero y un CTA que agenda por Calendly, las 15 páginas de detalle por funcionalidad, y la cadena que convierte a un espectador anónimo del VSL en un lead identificado con todo su comportamiento. Importa porque es cómo se vende el producto y cómo se mide el tráfico. El grueso de la landing y el motor de atribución ya están arriba; el cuello real es que Martín pegue el código de seguimiento en la landing y arme el flujo de WhatsApp, más completar los espacios en blanco de las páginas de detalle.", "2026-08-15"),
  P("cerrar-la-auditora", "🛡️", "Cerrar la auditoría de seguridad antes de traer clientes", "#0E9B8E", 92, 85, 35, "Bloqueante duro: no podés onboardear un segundo cliente si le filtrás datos de otro. Los graves ya están tapados y queda la cola larga, así que pesa mucho pero cuesta menos que el go-live; va antes que cualquier feature.", "Llevar a cero los agujeros de seguridad antes de onboardear clientes reales. El problema de fondo: hay consultas que van a la base sin filtrar por cliente, y eso filtra datos de un cliente a otro. Está cerrado cuando no queda ni una fuga entre cuentas, las acciones de configuración quedaron aplicadas en producción, y las protecciones del navegador y los webhooks están endurecidas. Los agujeros graves ya están tapados; falta la cola larga.", "2026-07-25"),
  P("tooluse-core-de", "🧠", "El cerebro que actúa: MaKo deja de opinar y empieza a hacer", "#7C5CFB", 89, 88, 55, "El cerebro que actúa desbloquea Retro, semáforo y CRM explicable: es lo que hace al producto demostrable y vendible. Alto impacto pero build grande; ojo con la trampa de perfeccionarlo: alcanza la versión mínima que ya se muestra y se cobra.", "Hoy MaKo responde a ciegas: te da opiniones sin haber mirado un solo dato del negocio. Este proyecto lo convierte en un asistente que primero LEE (consulta tus leads, chats, reuniones y experimentos antes de contestar), después PROPONE (arma borradores que vos aprobás con un botón, nunca manda nada solo) y aparece metido dentro de cada pantalla. Sin esto no hay Retro que te reclame, ni semáforo que accione, ni CRM que se explique. Está listo cuando MaKo ve tus números de verdad y te propone la secuencia de mensajes concreta ahí donde estás parado.", "2026-08-31"),
  P("versionado-actualizaciones", "🔢", "Versionado + que la app se actualice sola", "#2F6FED", 86, 72, 20, "El multiplicador más barato de la lista: desde el viernes hay tres clientes adentro y cada push los deja mirando una versión vieja. Ya nos costó horas acá mismo (bugs reportados sobre builds viejos que ya estaban arreglados). Esfuerzo bajísimo y el ahorro es para siempre, por eso trepa arriba de features mucho más grandes.", "Hoy hacés un push y el que tiene la app abierta sigue viendo la versión anterior: prueba algo ya arreglado, reporta un fantasma, y se van dos horas de ida y vuelta. Este proyecto hace que las pestañas se enteren solas de que hay build nuevo y se refresquen, y para los cambios que no se pueden aplicar en caliente, un cartel que NO se va hasta que actualizás. Encima arranca el versionado en serio: números de versión, qué cambió en cada uno y desde cuándo. Listo cuando nadie —ni vos ni un cliente— vuelve a trabajar sobre una versión vieja sin enterarse.", "2026-07-20", { ts: CARGA_16J, text: "Creó el proyecto — Versionado, del 16/7. Tu párrafo se partió en tres tareas (#140-142)" }),
  P("mako-en-whatsapp", "💬", "MaKo en WhatsApp: el doer que funciona de verdad", "#7C5CFB", 80, 88, 50, "Es EL diferenciador del producto —hablarle a MaKo por WhatsApp como a un socio— y hoy funciona mal: no guarda contexto. Entregar un producto donde justo la magia falla quema la venta más rápido que no tenerla. Muy alto, pero abajo de la fecha dura y del versionado que cuesta un décimo.", "El doer bidireccional: MaKo escucha en el grupo de WhatsApp (texto y audio), entiende, consulta el negocio de verdad y responde o ejecuta con tu confirmación. Es la promesa central del producto. Hoy está roto en lo básico: no guarda el contexto de la conversación (hay que compararlo contra una respuesta de Claude para ver el bajón), no anda cuando se crea el grupo de un cliente, el grupo no se arma solo al escanear el QR, y los casos de uso con archivos y preguntas específicas están sin probar. Listo cuando le podés escribir tres mensajes seguidos, se acuerda de los tres, y hace lo que le pediste.", "2026-07-24", { ts: CARGA_16J, text: "Creó el proyecto — MaKo en WhatsApp, del 16/7. Propio y no dentro de Bandejas ni del Doer: lo tratás como bloque aparte" }),
  P("crm-automtico-leads", "🤖", "CRM automático: leads que avanzan solos", "#C8870C", 74, 80, 40, "Mueve leads solo con criterio de closer y eso es plata directa; el motor entero ya está en prod, solo falta el interruptor por cliente. Más abajo que el go-live porque justamente ese encendido lo cubre aquel, pero arriba de las features que todavía no facturan.", "MaKo mueve el lead de etapa con el criterio de un buen closer: agenda una reunión y tres horas después chequea si el tipo asistió, deriva a nutrición al que no agenda, marca el no-show, reactiva al que se enfrió. Son seis reglas que nunca pisan un dato que cargaste vos, dejan rastro con autor 'MaKo' y siempre aplican-y-después-piden-tu-OK con un aviso que no se puede ignorar. El motor entero ya está en producción, pero en simulación. Está listo cuando se prende por cliente y mueve leads reales sin quemar pólvora.", "2026-08-20"),
  P("recordatorios-de-juntas", "⏰", "Recordatorios de reuniones y follow-ups (chau n8n)", "#D6489B", 71, 78, 45, "El no-show es el asesino número uno del high-ticket y hoy la nutrición casi no corre: recordatorios y follow-ups son plata que se está fugando. Un poco abajo del CRM porque tiene más partes sueltas (matar n8n, dos bases), pero es money real y cercano.", "Traer DENTRO de la app todo el seguimiento que hoy vive en n8n, sobre otra base de datos y apagado: recordatorios de reunión (24h, 1h, 15 min), la tanda de follow-ups, la cobranza de cuotas vencidas y el mensaje post-llamada. El no-show es el asesino número uno del high-ticket y hoy la nutrición casi no corre. Además ataca el problema de tener dos bases que no se hablan y a Calendly procesado por las dos. Está listo cuando la app manda recordatorios y follow-ups sola y podemos apagar n8n.", "2026-08-20"),
  P("mako-escribe-la", "🖋️", "MaKo escribe la nutrición (y aprende tu voz)", "#1E9E57", 66, 70, 45, "Que el cliente no redacte 30 mensajes a mano baja la fricción de arranque y ayuda a vender/retener; F3 y el estudio de copy ya están. Menos urgente que encender lo que ya factura, pero multiplica el criterio de Martín a escala.", "Que el cliente no tenga que redactar 30 mensajes a mano. MaKo aprende cómo habla el negocio (mirando sus anuncios y su marca), escribe cada mensaje de la secuencia en esa voz, y el cliente solo revisa y aprueba. La misma máquina escribe también el copy de los anuncios y, más adelante, guiones de VSL y DMs. Multiplica el criterio de Martín a escala. F3 y el estudio de copy están hechos; falta encender el envío real y sumar los escritores de VSL/DM.", "2026-09-30"),
  P("arranque-del-cliente", "🧳", "Arranque del cliente: onboarding sin fricción", "#98A0AC", 63, 68, 45, "Un onboarding sin fricción hace que el cliente nuevo llegue solo a productivo, lo que sostiene la venta. Va debajo de los money-movers directos porque no factura por sí mismo, pero cuida la conversión del que ya entró.", "Que un cliente nuevo sea productivo con la menor fricción posible: un wizard que lo lleva de la mano por conectar integraciones, extraer su histórico, configurar tabs, cargar su negocio y correr la primera Retro; una vista SIMPLE por default (3 tareas + experimentos) con el kanban completo detrás de un toggle Avanzado; y el principio de pedir la MENOR config manual (primero defaults, después plantillas y sugerencias, y recién al final el editor a mano). Terminado cuando un cliente pasa el arranque solo, su histórico se extrae aunque cierre la pestaña, y ninguna pantalla lo obliga a 'armar' el sistema.", "2026-08-31"),
  P("motor-de-nutricin", "🤖", "Motor de nutrición multicanal + plantillas de Meta", "#D0504A", 61, 72, 30, "Convierte el funnel en acción sin manos y ya está completo en código; corre simulado. Esfuerzo marginal bajo, pero el encendido real vive en el go-live, así que su prioridad propia queda por debajo de prender el producto.", "El cerebro que decide y dispara la nutrición del lead según su etapa, con reglas para no comerse un baneo (demora al escribir proporcional, pausas al azar, tope de envíos) sobre WhatsApp y Email compartiendo la misma cohorte y un candado de 20h por lead. Más todo el circuito para redactar, validar y publicar plantillas de mensaje en Meta. Importa porque convierte el funnel en acción sin manos, y sin plantillas aprobadas no hay forma de reabrir la ventana de 24h. Motor y plantillas están completos en código; hoy corren en simulado (el encendido real se trata en el go-live).", ""),
  P("bandejas-de-whatsapp", "📥", "Bandejas de WhatsApp (oficial + no oficial por QR)", "#2F6FED", 58, 65, 40, "Es donde el equipo conversa con los leads y los dos canales ya están enviados; quedan piezas de cierre. Importa para operar pero no factura por sí solo, así que va en la banda media, abajo de lo que enciende ingresos.", "El inbox de WhatsApp fiel a la app nativa, sobre DOS canales: el oficial (la API de Meta vía Chatwoot, para el tráfico frío de los ads) y el no oficial por QR (el número real de venta del cliente, sin las restricciones de la API oficial). Leer y responder, multimedia, notas de voz, borradores, avisos en vivo, la ficha del lead a un clic y paridad total entre los dos canales. Importa porque es donde el equipo conversa con los leads. Los dos canales están enviados; quedan las piezas de cierre y el arranque asistido.", "2026-08-25"),
  P("agente-de-ads", "📈", "Agente de Ads: MaKo optimiza el gasto solo (con tu OK)", "#0E9B8E", 55, 70, 55, "La palanca de retorno más directa ahora que se puede escribir en Meta, pero falta el agente que orquesta y el producto todavía no vende. Feature potente que rinde recién cuando hay cliente pagando, por eso mitad de tabla y no arriba.", "Cerrar el círculo entre lo que gastás y la plata que entra de verdad: que MaKo proponga (y con tu OK ejecute) subirle presupuesto a los anuncios que venden, apagar los que queman plata y duplicar ganadores, usando la plata cobrada por anuncio como brújula en lugar de solo la cantidad de leads. Es la palanca de retorno más directa ahora que ya podemos escribir en Meta y el tool-use está vivo. Terminado = reglas de subir/apagar propuestas con datos, ejecución en un clic con rastro, y el histórico de veredictos guardado para detectar cuándo un anuncio lleva días quemando. Las piezas están listas; falta el agente que las orquesta.", "2026-10-01"),
  P("comunicacin-con-el", "🔔", "Comunicación con el dueño + señales de WhatsApp", "#7C5CFB", 53, 62, 45, "Convierte reportes en acción sin abrir la app y destraba el seguimiento del que no contesta; el perfil y la campanita ya están. Útil pero es más comodidad del dueño que venta nueva, así que banda media.", "Que el dueño reciba lo urgente y los resúmenes por donde prefiera (WhatsApp o email), pueda responder ahí mismo y que MaKo ejecute lo que le pide ('sí, dale' → pausar campañas), y que el CRM 'sienta' lo que pasa en WhatsApp: última respuesta, contactos, con qué número se habló. Importa porque convierte los reportes en acción sin abrir la app y destraba el seguimiento automático del que no contesta. El perfil, la campanita y los reportes al dueño ya están; falta que los reportes salgan por cada cliente, que MaKo actúe sobre lo que le respondés, y las señales finas por lead.", "2026-08-30"),
  P("funnel-como-fuente", "🧭", "El funnel como única fuente de verdad", "#C8870C", 51, 60, 50, "Cimiento que hace que todo lea el funnel real en vez de etapas clavadas, palanca 2 del roadmap. Habilita mucho pero no trae plata hoy y toca varias piezas, por eso queda en el medio, debajo de lo que factura ya.", "Que la definición de tu proceso comercial (etapas, transiciones, bandas, disparadores) sea lo que TODO lo demás consume, en vez de una pantalla suelta. El editor, la derivación automática y el rediseño conceptual ya existen; el norte es que MaKo, las métricas, los SLAs, la línea de tiempo y la nutrición dejen de tener las etapas clavadas en el código y lean el funnel. Terminado cuando agregar una etapa en /funnel se refleja solo en tableros, reglas y contexto de la IA, sin tocar una línea de código.", "2026-08-30"),
  P("cerrar-el-ciclo", "🎯", "Cerrar el ciclo con Meta: nueva campaña, salud y Purchase", "#D6489B", 49, 60, 60, "El CAPI Purchase hace que Meta optimice sobre la plata cobrada y no solo agendas, eso es ROI puro; pero depende de piezas bloqueadas y es esfuerzo alto. Money bueno pero no inmediato ni fácil, por eso mitad de tabla.", "Las tres piezas que faltan para manejar Meta de punta a punta sin salir de MaKo: lanzar campañas nuevas (describís la idea, subís los creativos y MaKo arma la estructura, la editás y sale en pausa), una vista que te dice si la cuenta está entregando bien y qué tocar, y avisarle a Meta cuándo cobraste de verdad para que optimice sobre la plata que entra y no solo sobre las agendas. Listo cuando publicás una campaña completa, la salud te sugiere sola y Meta aprende del cash cobrado.", "2026-08-15"),
  P("sistema-de-contexto", "🧩", "El contexto que hace que MaKo deje de responder genérico", "#1E9E57", 47, 58, 40, "Le da criterio propio del negocio a MaKo y ya está al 90%; falta enchufar números vivos y prompts sueltos. Base importante pero transversal y sin facturar por sí, va en la banda media-baja.", "El cimiento que le da a MaKo criterio propio del negocio: cada vez que responde arma su contexto sumando quién es + metodología + el perfil del cliente + una instrucción según la pantalla + el conocimiento que recupera (de cursos y áreas) + los datos del gráfico, y descarta lo que falle sin romperse. Además, todos los prompts del producto (33) se editan desde una pantalla, sin tocar código ni redeployar. Construido al ~90%; falta enchufarle los números vivos, registrar los prompts que quedaron sueltos y mejorar la búsqueda a escala.", "2026-08-15"),
  P("ficha-del-lead", "🪪", "La ficha del lead: toda la historia en una sola pantalla", "#98A0AC", 45, 55, 35, "Casi todo entregado, quedan colas de deuda técnica atadas al funnel fijo. Buena UX pero marginal para la plata ahora; esfuerzo bajo pero impacto acotado, así que media-baja.", "El rediseño completo del detalle del lead: un asistente que mueve el lead de etapa preguntando de a un paso, pestañas ordenadas (resumen, tracking, reuniones, datos del trato, historial), cuotas claras, el contrato leído por IA, tracking fino por persona, una pestaña de chat y análisis generado por MaKo. Se fusionó todo en una ficha ÚNICA, editable con un gesto. Está listo cuando abrir un lead te cuenta toda su historia en una sola vista y MaKo te redacta lo que falta. Casi todo entregado; quedan colas de deuda técnica.", ""),
  P("retro-real-rendicin", "🔎", "Retro real: que MaKo te rinda cuentas", "#D0504A", 44, 55, 55, "Cerrar el círculo de accountability es lindo pero es sobre todo herramienta para Martín, no venta nueva, y verificar ejecución es build considerable. Vale, pero no acerca a facturar, por eso banda media-baja.", "La Retro es el único cerebro que mira TODO el negocio: lee por áreas, te da veredictos, propone experimentos y tareas, y cuando aceptás los crea de verdad. El problema: la rendición de cuentas hoy es de mentira. MaKo chequea si tocaste 'Aceptar', no si realmente lo hiciste. Este proyecto cierra el círculo: que detecte fugas con criterio, verifique lo que EJECUTASTE contra lo que prometiste, te lo reclame y no te vuelva a proponer lo que ya ignoraste. Terminado cuando la Retro deja de ser un informe caro que pedís cuando querés y pasa a ser un coach que te persigue.", "2026-08-25"),
  P("pulso-diario-vista", "💓", "Pulso diario: la vista Hoy + un semáforo que piensa", "#2F6FED", 42, 52, 50, "El latido diario que te reclama es engagement del dueño más que ingreso, y arranca casi de cero. Útil para no perderse pero lejos de la caja, va debajo de las features que tocan plata.", "Lo que a todos los pilares del producto les falta por igual: un LATIDO barato y periódico que lee qué se hizo de verdad, razona liviano y te reclama o te avisa por campanita y WhatsApp. En vez de un dashboard que abruma, una vista 'Hoy' con las 3 secuencias que más plata mueven, un semáforo que ya no solo linkea sino que razona alertas nuevas, y una bandeja de propuestas que aparece cuando NO estás mirando el chat (sin pop-ups que te bloqueen para lo no urgente). Terminado cuando abrís MaKo a la mañana y sabés exactamente qué hacer, y si no lo hacés, te lo reclama.", "2026-09-20"),
  P("mako-app-mobile", "📱", "MaKo App Mobile — el cliente ve lo suyo desde el celular", "#7C5CFB", 41, 58, 72, "Buena para retención y percepción de producto, pero llega DESPUÉS del go-live y las features que facturan: el cliente primero tiene que tener valor en la web. Esfuerzo alto (app aparte + re-adaptar cada vista que entra) e impacto medio, por eso banda media-baja.", "Una app móvil para que el cliente vea y actúe sobre su negocio desde el teléfono. Regla de oro: NO todas las pestañas van a mobile, y las que van se re-adaptan 100% (no se 'encoge' el desktop). CANDIDATAS a mobile (consumo rápido + acción de 1 toque): la vista Hoy/Pulso (las 3 secuencias del día), el chat con MaKo (con audio, imágenes y aprobar propuestas), las notificaciones/campanita, la ficha del lead en modo LECTURA y aprobar/rechazar lo que MaKo propone. SE QUEDAN en desktop (densas, de trabajo fino): el Ads Manager, el editor de funnel, la Retro completa, los analistas (Closing/Script) y las tablas de analítica — en mobile a lo sumo un resumen que linkea al desktop. Decisiones abiertas: ¿PWA (una sola base, instalable, más barata) o app nativa (mejor push/cámara/voz)? y ¿qué rol ve qué en mobile? Terminado cuando el dueño/closer abre el celu, ve su Hoy, responde a MaKo por voz y aprueba una acción, sin necesitar la compu.", ""),
  P("multiinquilino-workspace", "🏢", "Cada cliente en su propia cuenta, aislado del resto", "#0E9B8E", 40, 65, 20, "Habilitó vender a un segundo cliente sin filtrar datos, pero el núcleo ya está entregado y andando: queda poquísimo por hacer. Alto valor estratégico ya cobrado, así que como trabajo pendiente su prioridad es baja.", "Pasar el dashboard de 'una sola cuenta donde todos veían los datos de Mauricio' a multi-cliente: cada usuario tiene su cuenta aislada, hay un panel de agencia para 'entrar como' cualquier cliente, y cada uno corre con SUS credenciales y SU ingesta. Sin esto no se puede vender MaKo a un segundo cliente sin filtrarle datos ajenos. El núcleo está entregado y andando en producción.", ""),
  P("experimentos-como-fuente", "🧪", "Experimentos: el único lugar donde MaKo concluye con datos", "#7C5CFB", 38, 48, 45, "El único lugar donde MaKo concluye con datos, pero el ciclo ya está y falta el combustible (cash por creativo). Importa para el criterio pero no mueve caja hoy, banda baja.", "Acá una hipótesis se vuelve un experimento medible: con línea de base, medición automática y veredicto al cerrar. Es a propósito el único lugar donde MaKo afirma; en el resto sugiere abrir un experimento, nunca concluye, y solo las verdades ya validadas entran a su contexto. El ciclo, la medición y las tres vistas ya están; falta el combustible (plata cobrada por anuncio, histórico de veredictos) y automatizar el cierre. Se ve terminado cuando los experimentos se cierran solos y las decisiones se apoyan en cash real por creativo.", "2026-09-30"),
  P("dashboard-de-analtica", "📊", "Tablero de analítica de marketing (el núcleo de reporte)", "#C8870C", 37, 60, 20, "El núcleo de reporte sobre el que todo razona, pero está entregado de punta a punta: no hay casi nada que hacer. Cimiento valioso ya construido, por eso baja como pendiente aunque su valor sea alto.", "El producto original y el cimiento de todo lo demás: el tablero que convierte Meta, Calendly, el VSL y los pagos en pantallas para decidir. Vista General ('tu norte' con objetivo, ritmo y fecha estimada de llegada), Marketing (CAC en tres niveles, ROAS, anuncios ganadores con veredicto), Comercial (cohortes, ciclo de venta, no-show) y Plata/Cobranza (vendido/cobrado/por cobrar, plan de cuotas, contrato leído por IA, a quién cobrarle). Es la capa de números confiables sobre la que MaKo razona: sin esto no hay doer ni semáforo ni Retro. Entregado de punta a punta.", ""),
  P("rplica-de-meta", "📋", "Ads Manager propio + escribir de vuelta a Meta", "#D6489B", 36, 55, 20, "El Ads Manager con escritura a Meta ya está entregado y probado con 27 campañas reales. Cierra un loop importante pero está hecho; queda poco, así que baja en la lista de lo pendiente.", "Un Ads Manager dentro de MaKo: navegar campañas, conjuntos y anuncios como en Meta y ESCRIBIR de vuelta (pausar/activar, presupuesto, renombrar en lote con nomenclatura, editar público/anuncio/conjunto) sin salir de la app. Cierra el loop ver→decidir→accionar que un dashboard de solo lectura no da. Entregado y probado con 27 campañas reales: cada cambio llega a Meta con manejo de error de verdad (Meta a veces responde OK con un error adentro), habilitado solo para el dueño, y el renombrado en lote aplica una nomenclatura jerárquica consistente.", ""),
  P("cimientos-de-datos", "🔌", "Cimientos de datos: conectores e ingesta de todas las fuentes", "#1E9E57", 35, 62, 20, "La cañería que alimenta todo, entregada con webhooks e histórico corrido. Sin esto no hay nada, pero ya está: como trabajo por delante casi no queda, prioridad baja pese a su peso.", "La cañería que alimenta todo el resto: los conectores a Meta Ads (rendimiento por anuncio + presupuestos), Meta Lead Ads (formularios que entran solos, cruzados por teléfono), Calendly (agendas que entran solas + histórico), el VSL (YouTube y Panda) y los eventos de conversión de vuelta a Meta (CAPI). Sin ingesta confiable e histórico cargado, ninguna vista ni MaKo tiene con qué razonar. Cada fuente quedó con su webhook, su repaso diario de seguridad y su carga histórica corrida. Entregado.", ""),
  P("diseno-simple", "✨", "Diseño SIMPLE en toda la app (+ modo Avanzado)", "#0E9B8E", 34, 50, 40, "Aparece en TRES de tus siete bloques (Retro, Onboarding y el suyo propio): eso no lo hace urgente, lo hace transversal. Es un barrido, no una feature, y hacerlo tres veces por separado es hacerlo mal tres veces. Va al final, de una sola pasada, cuando el contenido de las pantallas ya dejó de moverse.", "Que ninguna pantalla abrume al que recién entra: SIMPLE por default (lo mínimo para decidir y actuar) y todo el detalle denso detrás de un toggle 'Avanzado' para el que lo quiera. Incluye las tabs que todavía no tuvieron su pasada (Ads Analyst y Closing Analyst) y una auditoría honesta de TODAS las demás preguntándole a cada una: ¿esto es simple o solo estoy acostumbrado? Importa porque una pantalla que abruma se abandona, y el cliente nuevo no tiene la paciencia que tenés vos. Listo cuando cualquier tab abre en SIMPLE y el modo Avanzado es una elección, no el default.", "2026-08-05", { ts: CARGA_16J, text: "Creó el proyecto — Diseño SIMPLE, del 16/7. Propio porque aparecía en tres de tus siete bloques: es un barrido, no una feature" }),
  P("cuentas-roles-y", "🔑", "Cuentas, roles y equipo", "#98A0AC", 33, 50, 20, "Cuentas con rol y tokens cifrados ya en prod: reemplazó la contraseña compartida y está cerrado. Necesario pero terminado, así que como pendiente va bajo.", "Reemplazar la contraseña compartida por cuentas reales con rol, sesión firmada, un flujo para cargar los tokens de cada integración, y roles de negocio por cliente (admin-cliente, closer, setter) con el control real del lado del servidor. Importa porque la contraseña única no distinguía a la agencia del cliente ni podía suspender a nadie, y un closer no tiene por qué ver la facturación. Terminado cuando cada persona entra con su cuenta de Google, el sistema valida contra la base en cada pedido, los tokens se cargan cifrados con tutorial, y dar de alta a un cliente crea su workspace y su admin en un solo paso. Ya está en prod.", ""),
  P("closing-analyst-analista", "📞", "Closing Analyst — el analista de tus llamadas de venta", "#D0504A", 31, 45, 25, "Ya entregado con dos vistas y puntaje robusto; alimenta objeciones y follow-ups. Aporta pero está hecho y no es la palanca de plata, banda baja.", "Trae las llamadas grabadas en Fathom, las matchea con cada lead por email, separa las de VENTA (R1/R2) de las de entrega de servicio (coaching a clientes ya cerrados) y corre Claude para puntuar la ejecución, marcar momentos clave, objeciones y el próximo paso. Importa porque se graba todo y solo una fracción son ventas reales: sin ese árbitro, las sesiones de servicio ensuciaban el análisis y hasta los R1/R2 del lead. Ya entregado: dos vistas (Métricas y Llamadas con la grabación embebida), puntaje robusto y R1/R2 re-vinculados solo con ventas.", ""),
  P("ads-analyst-analista", "🎬", "Ads Analyst — el analista de tus guiones de video ads", "#2F6FED", 29, 40, 25, "Entregado con 55 guiones; solo queda limpiar código muerto y un tablero alternativo. Analista lindo pero terminado y lejos de la caja, prioridad baja.", "Cruza la lectura de Claude sobre el guion (ángulo, hook, formato, estructura, diagnóstico) con la retención real de Meta por tramos y las agendas/cierres del CRM. La clave es separar lo que envejece (las métricas vivas, nunca congeladas) de lo estable (la lectura del guion, una por anuncio), así un guion se juzga por su desempeño ACUMULADO. Ya entregado (55 guiones): Patrones, un cuadrante de retención calibrado, un valorador de guiones nuevos, taxonomía editable de ángulos/avatares e imágenes leídas por OCR. Solo queda limpiar código muerto y un tablero alternativo.", "2026-07-25"),
  P("reskin-de-la", "🎨", "Reskin de la app + identidad MaKo", "#0E9B8E", 27, 42, 40, "Pulido transversal que nunca termina del todo y está mayormente hecho: es justo el tipo de perfeccionamiento que no factura. Ayuda a que usen la app pero no acerca la venta, va bajo.", "Dejar toda la app con un mismo look, prolijo y alineado a la landing, pantalla por pantalla (el tablero de marketing, el funnel, los analistas, la Retro), con el sidebar plegable por grupos, la identidad de MaKo (logo, voz rioplatense, cada gráfico con su análisis de IA al lado) y los textos migrados a R1/R2. Importa porque una app despareja se siente a medio hacer y frena que la usen; es transversal y nunca termina del todo. Listo cuando no quede ninguna pantalla con el estilo viejo ni ningún gráfico sin su ✦ de MaKo. Mayormente hecho.", "2026-09-30"),
  P("board-plan-perro", "🐕", "Board /plan — el Perro Guardián que prioriza", "#7C5CFB", 25, 38, 30, "El tablero de priorización ya está entregado y poblado; solo quedan cierres de desarrollo. Herramienta interna útil pero sin impacto en plata, baja.", "El tablero donde se planifica y prioriza TODO el roadmap: un Trello propio (renombrado /plan) con los proyectos como pieza de primera clase, columnas de prioridad, checklists que calculan el avance, historial de cambios y un mismo componente para agencia y cliente. Encima, un 'Perro Guardián' (MaKo) que prioriza al crear una tarea, la debate, cuida que el backlog sea una pirámide sana y ordena los proyectos del 1 al 10 sin empates. Entregado y poblado con el roadmap sacado de la memoria; solo quedan cierres de desarrollo.", ""),
  P("cs-analyst-analista", "🩺", "CS Analyst: analista de retención (anticipar bajas)", "#C8870C", 23, 42, 35, "Barato y reusa toda la infra del Closing, y anticipar bajas retiene plata; pero está sin arrancar y es post-venta, cuando ya haya clientes que se puedan ir. Idea rentable pero futura, banda baja-futuro.", "El gemelo del Closing Analyst pero sobre las llamadas de ENTREGA del servicio, que hoy se transcriben y se tiran a la basura. Es la función nueva más rentable y barata porque reusa toda la infra del Closing y le suma un termómetro de baja por cliente: cruza el ánimo de la última llamada con la cuota impaga y otras señales para ver quién se va a ir antes de que se vaya. Terminado = llamadas de servicio analizadas con resumen, riesgos y próximos pasos, un termómetro por cliente y alertas de baja que le llegan al dueño. Sin arrancar; los datos ya existen, solo se descartan.", "2026-09-15"),
  P("skills-de-claude", "🛠️", "Skills de Claude Code + mapa del código + gasto de IA", "#D6489B", 21, 35, 25, "Herramientas de construcción y medición de costo, ya armadas y subidas; lo que queda es usarlas como hábito. Acelera el desarrollo pero no vende, prioridad baja.", "Las herramientas de construcción y de medición que hacen a MaKo un producto barato de armar y con las cuentas claras: recetas a medida del repo que evitan errores repetidos (más algunas públicas seleccionadas), un mapa navegable del código para no perderse, y el registro de cuánto cuesta cada operación de IA contra un saldo cargado a mano. Importa porque acelera el desarrollo y da transparencia del costo de cada funcionalidad. Ya está todo armado y subido; lo que queda es usar las recetas como hábito.", ""),
  P("growth-vender-mako", "📣", "Growth — vender MaKo hacia afuera", "#1E9E57", 18, 55, 55, "Es vender MaKo hacia afuera, pero a propósito va DESPUÉS de que el producto haga las cosas de verdad: vender algo a medio hacer quema pólvora. Impacto eventual alto pero deliberadamente futuro, por eso abajo.", "El marketing del producto (no el producto en sí): venderle MaKo a cualquiera que corra un VSL Funnel. Incluye la oferta por niveles que desbloquea según la situación del cliente, muchos anuncios donde cada uno vende una sola funcionalidad (modelo Claudio Conde), testimonios, la página de gracias post-agenda, demos por funcionalidad y un mapa de uso. Importa para crecer, pero va a propósito DESPUÉS de que el producto haga las cosas de verdad: vender algo a medio hacer quema pólvora y reputación. Por eso casi todo es a futuro y de prioridad baja.", ""),
  P("canales-fros-bot", "🧊", "Canales fríos: bot que contiene + entrada por IG y mail", "#98A0AC", 12, 35, 60, "Arranque lejano que depende de que todo el resto ya funcione solo, y está sin empezar. Suma canales pero es esfuerzo alto sin plata cercana, zona de futuro.", "Sumar los canales de entrada fríos sin quemar los números de venta. Un bot en la línea oficial que recibe el tráfico frío de los ads, lo contiene y recién ahí lo pasa al número de venta ya tibio; más el patrón de que el lead escriba primero (link con palabra clave + QR en vivo), que baja muchísimo el riesgo de que nos bloqueen la línea. Suma también los DMs de Instagram y un buzón de mail por lead a la bandeja única. Es de arranque lejano y depende de que el resto ya funcione solo; hoy está todo sin empezar.", ""),
  P("infraestructura-propia-e", "🧰", "Infraestructura propia + escala de mensajería", "#D0504A", 8, 30, 65, "Trabajo de fondo muy a futuro; hoy nada lo frena y no acerca ninguna venta. Importa a mediano plazo cuando haya volumen, pero ahora es esfuerzo puro sin caja, casi al fondo.", "El trabajo de fondo que hace a MaKo independiente de la agencia y listo para muchos clientes: pasar la base de datos, el hosting y el dominio a nombre propio (con la landing en la raíz, no en /vsl), un método para actualizar sin cortarle a los que están probando, y cuentas propias por cliente para email y WhatsApp no oficial (hoy usan una única cuenta de MaKo que se topa con los límites de envío al escalar). Importa a mediano plazo pero hoy nada lo frena. Listo cuando MaKo corre en infra propia, con actualizaciones ordenadas, y cada cliente con volumen usa su propia cuenta. Muy a futuro.", ""),
  P("copiloto-en-vivo", "🎧", "Copiloto en vivo de la llamada", "#2F6FED", 5, 45, 90, "El sueño grande y el diferenciador máximo, pero choca con transcripción en vivo que no existe en el stack: costo y dificultad altísimos, sin arrancar. Moonshot lejano, el último de la lista.", "El sueño grande: un copiloto que escucha la llamada de venta en tiempo real y le va sugiriendo al closer respuestas y manejo de objeciones mientras habla, alimentado por el cerebro de copywriting y closing que ya tenemos curado. Es el diferenciador máximo del producto, pero es lo único de todo el plan que choca con algo que hoy no existe en el stack: transcripción en vivo. Terminado = la llamada transcripta en vivo + sugerencias al instante durante la reunión. Es una idea, sin arrancar; queda lejos por dificultad y costo.", ""),
];

// [num, title, projectIds[], score, prog, impacto, esfuerzo, razon, detalle]
type Row = [number, string, string[], number, number, number, number, string, string];
const SEED: Row[] = [
  [1, "MaKo ya lee el negocio (6 fuentes conectadas)", ["tooluse-core-de"], 40, 100, 42, 10, "Cimiento del doer (MaKo lee 6 fuentes) pero YA está al 100%: fue clave para todo lo de arriba, aunque hecho no ocupa punta. Score medio por su impacto histórico, no por urgencia.", "MaKo dejó de estar mudo: ahora puede consultar tus leads, la ficha de cada uno, el historial de WhatsApp, las reuniones, tu base de conocimiento y el estado de los experimentos, siempre acotado a tu propia cuenta. Tiene su pantalla propia y ya medimos cuánto cuesta cada consulta en IA."],
  [2, "Que MaKo hable con tus números reales, no de memoria", ["tooluse-core-de", "funnel-como-fuente"], 98, 25, 92, 18, "El quick-win más claro de todo el lote: inyectar el resumen vivo del funnel al chat es lo más fácil y lo que más mueve la aguja, y destraba semáforo/Retro/CRM que lo necesitan. Le gana a la #3 y #4 del mismo proyecto por menor esfuerzo.", "Cuando charlás con MaKo hoy, opina sin ver el estado real del funnel. La pieza clave: meterle un resumen vivo de tu embudo y tus métricas al arranque de cada conversación, para que cite números de verdad antes de responder. Es lo más fácil de hacer y lo que más mueve la aguja."],
  [3, "Que MaKo proponga secuencias y vos las aprobés con un botón", ["tooluse-core-de", "mako-escribe-la"], 72, 0, 80, 58, "El 'proponer y aprobás con un botón' es la versión mínima vendible del doer, corazón de poder vender. Alto impacto pero más esfuerzo que la #2, por eso va abajo de ella pero arriba de la media.", "Elegiste el camino 'leer y proponer, nunca mandar solo'. MaKo arma el borrador (un WhatsApp, una campaña en PAUSA, una secuencia de nutrición) y vos lo aprobás inline, sin sorpresas. Todo lo que sale de verdad pasa siempre por el filtro de permiso y confirmación: nada se dispara por atrás."],
  [4, "Prender los distintos MaKo y meterlos en cada pantalla", ["tooluse-core-de", "ficha-del-lead", "experimentos-como-fuente"], 67, 20, 68, 52, "Rutear los modos y embeber MaKo en cada pantalla cierra la promesa multi-agente de la landing; impacto bueno pero esfuerzo transversal. Menos directo a facturar que la #2/#3.", "El 'multi-agente' que promete la landing hoy es un solo MaKo: los modos Analista, Comparador y Closer están escritos pero apagados. Hay que rutear cada pedido al modo que corresponde y llevar el MaKo con números vivos a funnel, ficha del lead, experimentos, email y closing. Hoy solo WhatsApp lo tiene embebido."],
  [5, "El interruptor de envío tiene que ser por cliente, no global", ["golive-encender-el", "motor-de-nutricin", "crm-automtico-leads"], 94, 33, 88, 38, "Interruptor de envío POR cliente es el candado que habilita el piloto seguro: sin esto no hay go-live sin quemar leads ajenos. Proyecto #1 (98) y bloqueante puro, arriba casi de todo.", "Hoy los envíos de nutrición, email y CRM automático se prenden para TODOS los clientes de una: encender uno le mueve y contacta leads a cualquiera, y quema pasos como si fueran de mentira. Hay que poder prenderlos cliente por cliente para hacer un piloto seguro. El email ya funciona así; falta pasar nutrición y CRM automático al mismo esquema."],
  [6, "Salvar los datos de Meta antes de que los borre (URGENTE)", ["golive-encender-el", "cimientos-de-datos"], 87, 0, 82, 30, "Fuga de datos irreversible: Meta borra a los 90 días y no se guarda campaña/anuncio de origen. Urgencia real contra reloj + esfuerzo medio-bajo, corre entre o no el cliente. Sube por daño irrecuperable.", "Meta borra las respuestas de los formularios de leads a los 90 días y no se recuperan. Además, el anuncio y la campaña de origen de cada lead nunca se están guardando. Hay que empezar a guardar todo eso en la ingesta y rescatar lo que todavía esté dentro de la ventana. Corre contra reloj, entre o no el primer cliente."],
  [7, "Conectar WhatsApp no oficial, email y la primera plantilla en vivo", ["golive-encender-el", "bandejas-de-whatsapp", "motor-de-nutricin"], 80, 0, 85, 48, "Conectar WA no oficial + email + primera plantilla en vivo ES el go-live del primer cliente real, lo que permite mostrar y cobrar. Más esfuerzo/dependencias que la #5, por eso apenas debajo.", "Conectar el WhatsApp no oficial por QR usando un chip descartable (nunca el personal) y verificar que el espejo del chat quedó vivo de verdad (puede decir 'conectado' y estar muerto en silencio). Verificar el dominio de email del cliente y hacer una prueba real. Y probar por primera vez el envío de una plantilla de WhatsApp a Meta con las credenciales del cliente."],
  [8, "Dejar la infra de producción y el multi-cliente redondos", ["golive-encender-el", "multiinquilino-workspace"], 74, 25, 74, 40, "Cerrar infra de prod y últimos cabos mono-cliente destraba el go-live (secreto Chatwoot, migraciones que fallan calladas). Bloqueante pero menos palanca directa de venta que la #5/#7.", "Cargar el secreto del webhook de Chatwoot en producción (sin él, se rechaza y la nutrición deja de pausarse cuando el lead contesta). Confirmar que todas las migraciones corrieron (un bug caro: si no corren, las inserciones fallan calladas). Y sacar los últimos cabos que asumen un solo cliente: reuniones de Fathom, emails internos y los recordatorios que deben salir al canal de cada cliente."],
  [9, "Los agujeros graves y medios ya tapados", ["cerrar-la-auditora"], 42, 100, 45, 8, "27 hallazgos graves/medios YA cerrados: era el gate de seguridad pero está al 100%. Score medio por lo crítico que fue, sin punta por estar hecho.", "27 hallazgos verificados y cerrados. Se pasaron las consultas que filtraban datos entre clientes a la vía segura, el webhook de Chatwoot ahora rechaza lo que no viene firmado, y se cubrieron inyección de prompts, subida de avatares, accesos indebidos, protección contra pedidos falsos y límite de intentos de login."],
  [10, "Tapar las fugas entre clientes que quedan", ["cerrar-la-auditora", "multiinquilino-workspace"], 76, 0, 78, 42, "Tapar las fugas cross-tenant restantes es requisito duro ANTES de traer clientes: sin esto no se puede vender a un segundo sin filtrarle datos. Proyecto #3 (92), bloqueante de onboarding.", "ANTES de traer clientes: el webhook de Chatwoot busca leads sin filtrar por cliente, el tracking del VSL y la landing va a la base sin acotar, y unas vistas de datos no tienen la columna de cliente. La regla que evita que esto vuelva: prohibir la conexión cruda a la base sobre las tablas de clientes fuera del único archivo autorizado."],
  [11, "Aplicar en producción lo que ya está resuelto en código", ["cerrar-la-auditora", "golive-encender-el"], 83, 0, 76, 14, "Aplicar en prod lo ya resuelto en código (secreto Chatwoot) es baratísimo y sin él la nutrición no se pausa cuando el lead contesta. Quick-win puro: casi tanto impacto que la #10 con una fracción del esfuerzo.", "Cargar el secreto del webhook de Chatwoot en producción y pasárselo en la URL de Chatwoot (sin él, en producción se rechaza todo y la nutrición deja de pausarse cuando el lead contesta). Aplicar la migración de emails en minúsculas con sus índices. Y, opcional, forzar el origen del beacon de tracking."],
  [12, "Endurecer el navegador, evitar duplicados y sumar tests", ["cerrar-la-auditora"], 48, 20, 48, 40, "Endurecer CSP, evitar dobles disparos y sumar tests es cola larga de auditoría: importa pero es más pulido que sangría de plata. Debajo de las otras tres tareas del mismo proyecto.", "Falta endurecer la política de seguridad del navegador (hay que probarla ahí mismo), evitar que un webhook repetido dispare dos veces la misma acción, y tests que verifiquen que cada consulta queda de verdad acotada al cliente correcto. Ya hay tests de las reglas de etapa y del planificador."],
  [13, "Las 6 reglas del motor + el planificador (en simulación)", ["crm-automtico-leads"], 41, 100, 42, 10, "Las 6 reglas + planificador YA al 100% pero en simulación: motor listo, no factura hasta prenderse (eso es la #15). Score medio-bajo por estar hecho pero sin cerrar loop de venta.", "Las seis reglas que deciden cómo avanza un lead, la etapa de Reactivación y el planificador que arma el plan sin aplicarlo todavía. En la tab de Funnel hay una sección que explica en criollo qué mueve cada lead y por qué. Todo probado y sin el bug del bucle infinito."],
  [14, "Aplicar de verdad + red de confirmaciones + plantillas + hora exacta", ["crm-automtico-leads", "motor-de-nutricin"], 43, 100, 44, 12, "Aplicación real + red de confirmaciones + plantillas + hora exacta: al 100% y ya endurecido. Gran laburo hecho, pero como está cerrado no ocupa punta; su valor se libera al encender (#15).", "La parte que aplica cada movimiento con una red que evita repetir la misma acción sobre un lead, con deshacer quirúrgico y un aviso que no se puede cerrar hasta que confirmes. Pasó por una revisión durísima que dejó siete arreglos. Sumamos las plantillas de nutrición (no agenda, no-show, no paga, reactivación) y guardamos la HORA de cada reunión para que el chequeo de asistencia caiga a las 3 horas exactas."],
  [15, "Prenderlo por cliente + auto-completar datos + soltar el funnel fijo", ["crm-automtico-leads", "golive-encender-el", "ficha-del-lead"], 68, 15, 66, 40, "Prender el CRM auto por cliente + soltar el funnel fijo es lo que convierte el motor hecho en acción vendible. Impacto bueno pero depende del piloto; menos inmediato que los go-live de #5/#7.", "El interruptor del CRM automático es global: prenderlo mueve leads de todos. Hay que poder prenderlo en un piloto y mirar el primer lote real. Sumar una regla que autocompleta los 'datos sin marcar' leyendo el contrato con IA (la versión automática del asistente manual). Y soltar el funnel fijo: hoy el motor asume el embudo estándar, así que una etapa custom no dispara su nutrición."],
  [16, "Vista para espiar qué HARÍA el motor antes de prenderlo", ["crm-automtico-leads"], 57, 0, 52, 22, "Vista para espiar qué haría el motor antes de prenderlo: barata y da confianza para dar el interruptor, pero es apoyo del go-live del CRM, no la palanca directa. Score medio.", "Poder ver el plan que arma el motor en simulación sin esperar al chequeo automático, para auditar qué haría MaKo con cada lead y agarrar confianza antes de dar el interruptor."],
  [17, "Recordatorios de reunión propios (24h, 1h, 15 min)", ["recordatorios-de-juntas"], 70, 30, 70, 34, "Recordatorios propios de reunión atacan al no-show, el asesino #1 del high-ticket: plata directa por asistencia y ya vamos 30%. Menor esfuerzo que otras del proyecto (ya tenemos la hora), sube.", "Hoy los recordatorios los manda n8n a través de Chatwoot. Ya capturamos la hora de cada reunión desde Calendly; falta programarlos y mandarlos por nuestro propio canal (WhatsApp o email) y jubilar el workflow de n8n."],
  [18, "Follow-ups + el mensaje post-llamada que redacta MaKo", ["recordatorios-de-juntas", "motor-de-nutricin", "closing-analyst-analista", "mako-escribe-la"], 52, 0, 54, 40, "Follow-ups + mensaje post-llamada que redacta MaKo: recupera nutrición apagada, impacto medio pero depende del motor y del análisis de llamada. Debajo de los recordatorios (#17) que pegan más directo.", "La tanda de follow-ups vive en n8n, apagada. Hay que rearmarla como secuencia dentro del motor de nutrición y prenderla. Y que apenas termina una llamada, MaKo redacte el follow-up usando el análisis de la llamada y la voz del cliente, con un borrador a un clic cuando el lead viene caliente."],
  [19, "Cobranza por WhatsApp que arranca desde los pagos", ["recordatorios-de-juntas", "motor-de-nutricin"], 65, 0, 60, 34, "Cobranza por WhatsApp desde las cuotas trae plata que YA se vendió pero no entró; gatillo claro (cuota vencida→secuencia). Buen retorno directo, esfuerzo medio; arriba de #18 por tocar cash.", "La info de cobranza (vendido, cobrado, pendiente y el plan de cuotas) ya está cargada, pero nada dispara el seguimiento. Usar las cuotas como gatillo: cuota vencida arranca una secuencia de cobranza por WhatsApp que se corta sola cuando entra el pago."],
  [20, "Unificar las dos bases (la app piensa, n8n ejecuta)", ["recordatorios-de-juntas", "motor-de-nutricin"], 41, 0, 40, 58, "Unificar las dos bases (app piensa, n8n ejecuta) es limpieza de deuda de infra: importante para dejar de tener split-brain, pero alto esfuerzo y poco impacto directo en facturar ahora. Abajo.", "Hoy la app y n8n corren sobre dos bases de datos distintas que no se cruzan, y Calendly lo procesan las dos. La idea: que la app decida la nutrición con el funnel y el VSL, y que n8n solo ejecute lo que quede pendiente, o directamente lo apagamos."],
  [21, "Datos aislados por cliente, hasta con la caché", ["multiinquilino-workspace"], 41, 100, 45, 10, "Aislamiento por cliente hasta en la caché: cimiento del multi-tenant, YA al 100%. Fue crítico para poder vender a un segundo cliente, pero hecho no ocupa punta.", "Cada tabla ahora sabe a qué cliente pertenece, y hay una capa que resuelve de quién es cada pedido (usuario a su cuenta; agencia entrando como alguien vía una cookie firmada; sin definir, se corta por seguridad). Toda consulta queda filtrada al cliente correcto sola, incluso cuando pasa por la caché, que era justo donde se filtraban datos."],
  [22, "Panel de agencia + 'Entrar como' un cliente", ["multiinquilino-workspace"], 38, 100, 40, 8, "Panel de agencia + 'Entrar como' al 100%: útil operativamente pero es tooling interno ya cerrado, no palanca de venta. Score bajo-medio por estar hecho.", "La agencia, sin entrar como nadie, ve su propio panel con las pestañas de Clientes (crear, pausar, renombrar) y Usuarios. El botón 'Entrar como' pone una cookie firmada y muestra un cartel de que estás impersonando."],
  [23, "Cada cliente con sus credenciales e ingesta en vivo", ["multiinquilino-workspace"], 39, 100, 42, 10, "Credenciales e ingesta por cliente al 100%: necesario para escalar clientes reales, ya entregado. Sin urgencia ni loop de venta pendiente, queda en baja.", "Cada cliente usa su propio token para conectarse a los servicios, y las vistas en vivo se muestran solo si esa integración está conectada. La ingesta recorre todos los clientes activos aislando errores: si uno falla, no arrastra a los demás."],
  [24, "La Retro que lee todo el negocio y te arma el plan", ["retro-real-rendicin", "experimentos-como-fuente"], 43, 100, 48, 12, "La Retro que lee todo y arma el plan está al 100% y en prod, pero su valor real (que verifique lo EJECUTADO y te reclame) vive en la #25, aún sin arrancar. Score medio: informe caro hecho, coach todavía no.", "MaKo recorre el negocio por áreas y la ejecución en vivo, te da veredictos y, cuando aceptás, crea de verdad los experimentos y las tareas (sin duplicar si repetís). Vive en tres pestañas: Retro, Experimentos y Conclusiones. Ya está en prod."],
  [25, "Que MaKo verifique lo que hiciste y te lo reclame", ["retro-real-rendicin", "board-plan-perro"], 36, 0, 42, 55, "Corazón de la Retro, pero es accountability/coaching: no trae plata más rápido. Pesa más que el pulido de la ficha (37-40), menos que lo que destraba el arranque del cliente (46).", "El corazón del proyecto. Hoy la Retro mira si tocaste 'Aceptar', no si el experimento se ejecutó de verdad. Hay que cruzar lo aceptado con lo realmente hecho, reclamarte solo lo que quedó colgado y no volver a proponerte lo que ya ignoraste, con un chequeo barato que no queme plata."],
  [26, "Catálogo de fugas + objeciones que se repiten", ["retro-real-rendicin", "closing-analyst-analista"], 34, 0, 40, 48, "Catálogo de fugas + objeciones agrega criterio a la Retro, pero no factura solo. Similar a 29/31: útil a futuro, no urgente ni fácil, va al pelotón medio-bajo.", "Que MaKo juzgue con criterio (dos señales, no una) los patrones típicos que queman plata: escalar lo que no gana, gasto que sube y resultados que bajan, poca variedad de creativos, huecos del funnel, cobranza que se repite. Y traer las objeciones que ya salen del análisis de llamadas y mostrarlas como patrón."],
  [27, "Una conclusión por pantalla, lista al abrir", ["retro-real-rendicin", "dashboard-de-analtica"], 44, 25, 45, 35, "Más quick-win que sus hermanas de Retro: precomputar baja un costo real (13 min caros por corrida) y los datos ya están al 80%. Bajo esfuerzo la sube sobre 25/26.", "En vez de correr la Retro entera cada vez (es cara, unos 13 minutos), precomputar una conclusión accionable por pantalla después de la ingesta diaria. Así cada tab abre ya con su veredicto y baja el costo. Los bloques de datos ya están al 80%."],
  [28, "Vista Hoy + un latido que te reclama", ["pulso-diario-vista", "comunicacin-con-el"], 38, 20, 44, 52, "El latido de la vista Hoy suma reclamo, pero es infra de producto, no venta directa. Menos palanca que el termómetro de a-quién-llamar (30), que sí mueve cierres.", "Ya hay un bloque 'Hoy' embrionario con las juntas y la cola de acción. Falta el latido de verdad: un chequeo diario barato que lee qué se hizo, y si dejaste algo colgado te lo reclama por la campanita y por WhatsApp."],
  [29, "Semáforo que razona alertas, no que solo linkea", ["pulso-diario-vista", "dashboard-de-analtica"], 34, 0, 40, 48, "Semáforo que razona es lindo pero es pulido de una vista interna; no acerca a facturar. Queda a la par de 26/31, debajo de lo que enciende cliente.", "Hoy el semáforo son seis reglas fijas que terminan en un link, cero criterio. Que Claude mire las señales ya calculadas más la tendencia y arme alertas nuevas y accionables de un clic, con un pre-filtro barato para no gastar tokens de más."],
  [30, "Propuestas de MaKo cuando no estás en el chat + a quién llamar hoy", ["pulso-diario-vista", "tooluse-core-de", "comunicacin-con-el"], 45, 0, 52, 50, "Unificar las 4 temperaturas y ordenar a quién llamar primero es acción comercial directa = más cierres. Lo más 'plata' del pulso diario, por eso arriba de 28/29/31.", "Que MaKo te aparezca aunque no estés en el chat: aviso en la campanita, una bandeja de propuestas y una línea en el resumen diario por WhatsApp, nunca un pop-up que te frene para lo no urgente. Y un solo termómetro del lead (recencia de WhatsApp, clic de email, revisita al VSL, tono de la última llamada) que unifique las cuatro temperaturas que hoy se contradicen y ordene a quién llamar primero."],
  [31, "Briefing de la mañana + dónde está el cuello", ["pulso-diario-vista", "tooluse-core-de"], 33, 0, 40, 50, "Briefing matutino y cuello del funnel ayudan a decidir, pero cuelgan del cerebro de MaKo y no facturan por sí. Medio-bajo, junto a 26/29.", "Un briefing matutino con las 3 secuencias que más plata mueven, uno pre-llamada (VSL, Calendly y de dónde vino el lead en una sola pantalla) y un diagnóstico que te diga cuál es el cuello del funnel: la única palanca que hoy mueve la aguja. Todo colgado del cerebro de MaKo."],
  [32, "Editor de funnel + rediseño del proceso + Fathom (hecho)", ["funnel-como-fuente"], 35, 95, 40, 15, "Editor de funnel + rediseño ya al 95%: casi hecho, queda poco. No ocupa punta pese a ser cimiento; score medio por lo que resta.", "El funnel se deriva solo desde una definición liviana: tipos de etapa, bandas, disparadores automáticos y manuales, plantillas VSL y Webinar. La nutrición positiva quedó como estado derivado, el No Show se marca por reunión (R1/R2/R3) y hay reuniones excepcionales. Fathom marca asistencia solo con las llamadas de VENTA, para no ensuciar el dato con las de servicio."],
  [33, "Que los tableros lean el funnel, no cuatro etapas fijas", ["funnel-como-fuente", "dashboard-de-analtica"], 42, 15, 48, 52, "Palanca 2 del roadmap y desbloquea los SLAs (35), pero es generalización de tableros, no venta inmediata. Arriba de 35 (que depende de ésta), debajo de 34.", "Hoy las métricas del embudo están clavadas a cuatro etapas: si agregás una, los dashboards la ignoran y te mienten. Calcular tasa de cierre, distribución y limpieza desde tu funnel real y confirmar que sumar una etapa no rompe ningún tablero. Es la palanca número 2 del roadmap."],
  [34, "Que MaKo y la nutrición conozcan tus etapas reales", ["funnel-como-fuente", "tooluse-core-de", "motor-de-nutricin"], 46, 20, 55, 55, "Hacer la nutrición agnóstica al funnel = el motor de plata dispara en las etapas reales del cliente. La más cercana a facturar de todo el bloque funnel, por eso lidera sus hermanas.", "MaKo hoy opina del proceso sin saber cuáles son tus etapas. Hay que inyectarle el funnel real (etapas, disparadores, bandas). Y hacer la nutrición agnóstica: hoy una etapa a medida no dispara su secuencia (las plantillas cubren solo los funnels comunes), así que hay que derivar la secuencia desde el funnel y enrolar al lead según su etapa."],
  [35, "SLAs por etapa + alerta cuando un lead se estanca", ["funnel-como-fuente"], 29, 0, 36, 52, "SLAs por etapa dependen de que los tableros ya lean el funnel (33): bloqueada y sin impacto directo en venta. Va abajo, con la deuda técnica.", "Poner un límite de días por etapa, un criterio de salida y un registro de cada cambio de etapa para medir cuánto tarda un lead en cada paso y avisarte cuando se pasa. Es la palanca 3; necesita que los tableros ya lean el funnel. Incluye guardar de dónde salió cada reunión: Calendly, Google/Fathom o fuera de Calendly."],
  [36, "Asistente para mover el lead + pestañas ordenadas", ["ficha-del-lead"], 30, 100, 35, 5, "Hecho al 100% (asistente + pestañas de la ficha). No compite por la punta; score bajo-medio acorde a impacto ya cobrado.", "El diálogo para mover el lead ahora es un asistente centrado, con el logo de MaKo, una pregunta por paso ('¿hubo primera reunión? ¿segunda?'), con motivo, con la parte de Fathom omitible y un 'Atrás' que funciona de verdad. Las excepciones quedan guardadas. Las pestañas se renombraron a resumen, tracking, reuniones, datos del trato e historial, y el selector de etapa va a dos columnas."],
  [37, "Datos del trato + cuotas + reuniones + tracking + chat", ["ficha-del-lead"], 32, 95, 40, 15, "Datos del trato + cuotas + chat al 95%: prácticamente entregado, cola de deuda. Bajo-medio como todo lo ya casi cerrado de la ficha.", "La tarjeta de datos del trato (pagos, fiscales, servicio, promesa, obligaciones) con 'completar con IA leyendo el contrato' sin pisar lo cargado, y un solo botón de editar y guardar. Cuotas claras con aviso de si cuadran o no. Reuniones con las respuestas de Calendly por cada una. Tracking fino por persona a través de varias landings y VSLs. Y una pestaña de chat, con el contacto de WhatsApp asegurado en los tres puntos de alta."],
  [38, "Análisis de MaKo + reuniones automáticas + ficha única", ["ficha-del-lead"], 32, 95, 38, 15, "Análisis de MaKo + ficha única al 95%: casi listo. Poco por hacer, no ocupa lugar arriba.", "El análisis generativo del lead, con un candado por etapa, prompts editables y todo lo que viene de afuera tratado como no confiable (pasó una revisión de 18 agentes). La búsqueda automática de reuniones cruza Calendly, Fathom y Google Calendar y arranca en modo 'automático'. Y se fusionó todo en una ficha única: el modal solo muestra, la edición va por su ruta, y la ficha vieja se borró."],
  [39, "Datos sin marcar + Closer/Setter con foto + asistente Solucionar", ["ficha-del-lead", "cuentas-roles-y"], 31, 90, 38, 20, "Datos sin marcar + Solucionar al 90%: casi hecho, pulido final. Igual que 37/38, bajo-medio.", "'Datos sin marcar' como una sola fuente (tarjeta, badge rojo y botón Solucionar), el asistente que resuelve todo de una (trato, documentos y segunda reunión de Calendly), Closer y Setter con la foto del equipo y el closer detectado solo desde Fathom, y el deshacer completo del movimiento con historial que dice quién lo hizo."],
  [40, "Deuda: la timeline y el cierre atados a un funnel fijo", ["ficha-del-lead", "funnel-como-fuente"], 20, 10, 28, 60, "Deuda diferida por riesgo (timeline/cierre atados a funnel fijo) para funnels custom que el piloto no usa: perfeccionar sin facturar. De lo más abajo de mi lote.", "La línea de tiempo y las reglas de etapa dan por hecho el embudo estándar de dos reuniones e ignoran el funnel de cada cliente; para funnels custom (tres reuniones o más) hay que derivarlas. Y mover el cierre (monto y fecha) adentro de la sección de pagos con un solo botón de guardar: hoy el cierre se guarda por separado y arreglarlo es reescribir mucho, así que quedó diferido por riesgo."],
  [41, "Motor de nutrición por WhatsApp + reglas anti-baneo (hecho)", ["motor-de-nutricin", "bandejas-de-whatsapp"], 32, 100, 45, 5, "Motor de nutrición WhatsApp + anti-baneo al 100%: core valioso pero ya construido (corre en simulado; el encendido real es del go-live). Score bajo-medio por estar hecho.", "Motor que según la etapa del lead programa y dispara los mensajes, con reglas para no comerse un baneo y un candado de 20h por lead. Envío real por WhatsApp en horario laboral (9 a 17 MX). 28 plantillas para 13 etapas, sembradas solas por cliente, sin tocar nada a mano. El envío real vive detrás de un flag."],
  [42, "Email marketing sobre el mismo motor (Resend)", ["motor-de-nutricin"], 30, 100, 40, 5, "Email sobre el mismo motor, hecho al 100% y por cliente. Ya cobrado; no compite por la punta.", "Las secuencias de email son pasos del mismo motor: comparten cohorte, ritmo de envío y candado con WhatsApp. Envío por Resend, campañas a un segmento, seguimiento de aperturas y clics, y baja automática. Ya funciona por cliente, con flags, dominio y envíos propios."],
  [43, "Redactar, aprobar y publicar plantillas de WhatsApp en Meta", ["motor-de-nutricin", "mako-escribe-la", "bandejas-de-whatsapp"], 33, 100, 48, 5, "Circuito de plantillas de Meta al 100%: pieza clave para reabrir la ventana de 24h, pero ya entregado. Score medio-bajo por estar cerrado.", "Todo el circuito para mandar una plantilla a Meta: un validador de IA la corrige antes de enviarla, se publica, se sigue su estado y se puede editar la ya aprobada, con el motivo de rechazo real y un aviso del veredicto. Sin plantillas aprobadas no hay forma de reabrir la ventana de 24h."],
  [44, "Inbox oficial (Chatwoot): responder, multimedia, avisos (hecho)", ["bandejas-de-whatsapp"], 29, 100, 40, 5, "Inbox oficial Chatwoot al 100%. Entregado; ocupa lugar bajo pese a ser donde se conversa.", "El chat de WhatsApp oficial dentro de la app: leer y responder, mandar fotos, audio, video y archivos, notas de voz, emojis, ver el estado del mensaje, respetar la ventana de 24h, borradores y bloqueo con motivo. Los avisos de mensaje nuevo se detectan por la dirección del mensaje (el contador de no leídos siempre viene en cero) y la ficha del lead se abre a un clic."],
  [45, "Canal no oficial por QR: el número real de venta (hecho)", ["bandejas-de-whatsapp", "infraestructura-propia-e"], 29, 100, 40, 5, "Canal no oficial por QR al 100%, con paridad total. Hecho; bajo-medio como los demás entregados.", "El segundo canal: el número real de venta del cliente conectado por QR, sin las restricciones de la API oficial. Conexión, espejo del historial que no rompe nada, media a un espacio privado, envío con demora anti-baneo, borradores, lectura en vivo, agrupado por teléfono y avisos. Paridad total con el canal oficial."],
  [46, "Al entrar a WhatsApp, MaKo te arma toda la nutrición", ["bandejas-de-whatsapp", "arranque-del-cliente", "mako-escribe-la"], 54, 0, 58, 48, "Arranque que le pide a MaKo generar toda la nutrición y vos solo aprobás: baja la fricción de onboarding a casi cero = acerca a tener un cliente vivo y poder mostrar/cobrar. Lo más alto de mi lote.", "La primera vez que entrás (nada conectado, sin plantillas), un arranque que le pide a MaKo generar la nutrición de todas las etapas; vos solo aprobás y conectás. Tiene que registrar Y verificar el webhook, para no repetir el fallo silencioso que tuvimos con el espejo. Baja la fricción del arranque a casi cero."],
  [47, "Cerrar el canal no oficial: tildes, bloqueo, abrir desde el CRM", ["bandejas-de-whatsapp", "ficha-del-lead"], 30, 25, 34, 45, "Tildes, bloqueo y abrir chat desde el CRM: pulido de un canal ya enviado. No factura nuevo; queda medio-bajo frente a 46 que sí destraba arranque.", "Falta bloquear un contacto o teléfono, un componente de tildes compartido (los dobles ✓✓ todavía no se pintan del todo), abrir el chat directo desde la ficha del lead, y endurecer: un token propio por número, saber quién mandó cada mensaje manual y el flujo para reengancharse tras un baneo (chip nuevo + QR + el historial ya espejado)."],
  [48, "Biblioteca de copywriting que hace mejor a MaKo", ["mako-escribe-la", "sistema-de-contexto"], 39, 90, 35, 20, "Quick-win: cargar más ejemplos ganadores (90% hecho, poco esfuerzo) sube la calidad del generador/plantillas, un core de venta. Bajo impacto pero barato, por eso arriba de otras a medio hacer.", "MaKo escribe apoyado en una metodología curada (AIDA/PAS/BAB, gatillos emocionales, cómo se arma una secuencia que convierte) más un archivo de ejemplos reales que funcionan (swipe) para copiar el tono. Eso levanta la calidad del generador, del asesor de WhatsApp y de las plantillas. Falta cargar más ejemplos ganadores."],
  [49, "Aprender la voz → escribir la secuencia → mandarla a Meta", ["mako-escribe-la", "motor-de-nutricin", "bandejas-de-whatsapp"], 43, 100, 70, 45, "Aprender la voz y convertir en plantilla de Meta es un diferencial fuerte que acerca a vender, pero ya está al 100%: alto impacto histórico, no ocupa la punta. Le gana en valor a los escritores lejanos (51) pero por estar hecha va debajo de lo que hoy destraba plata.", "MaKo estudia los anuncios del negocio y arma una guía de su voz; después reescribe solo el texto de cada paso (los tiempos y la estructura quedan igual) y vos aprobás. Con un clic ese mensaje se convierte en plantilla de WhatsApp lista para aprobar en Meta, y elegís por paso si sale por el número oficial o por el no oficial."],
  [50, "Estudio de copy para anuncios", ["mako-escribe-la", "agente-de-ads"], 35, 100, 50, 35, "El escritor de copy de anuncios ya cierra el 'ghostwriter' del roadmap: impacto medio y esfuerzo bajo, pero terminado. Vale menos que el motor de voz completo (49) y queda en zona baja por estar hecho.", "MaKo escribe el copy de los anuncios de Meta apoyado en la misma biblioteca de copywriting y en el perfil del negocio. Cubre el 'escritor fantasma' que estaba en el roadmap."],
  [51, "Escritor de VSL + escritor de DMs + loop analizar→escribir→producir", ["mako-escribe-la", "ads-analyst-analista", "landing-de-venta"], 12, 0, 26, 72, "Escritores de VSL/DMs y el loop analizar→escribir→producir son explícitamente 'lejanos' y de alto esfuerzo, sin facturar nada hoy. Clásico pulido de feature 'por las dudas': abajo de todo, pierde contra cualquier onboarding o cierre de Meta.", "Hoy las pantallas de escritor de VSL y de DMs son solo un cartel de 'próximamente'. Falta el generador de guiones de VSL y el de DMs con el mismo patrón. Y el diferencial grande: encadenar Ads Analyst (detecta qué mejorar del guion) → escritor de anuncios (lo reescribe) → generador del creativo, todo de una pasada. Lejano."],
  [52, "Wizard de arranque + extracción del histórico en vivo (hecho)", ["arranque-del-cliente", "cimientos-de-datos"], 45, 100, 66, 50, "El wizard que fuerza conectar y arranca la extracción histórica es cimiento para que un cliente sea productivo (habilita vender), pero ya está al 100%. Alto impacto, sin lugar en la punta; por encima de las colas de onboarding pendientes por peso, debajo por estar hecho.", "El cliente nuevo pasa un wizard que no lo deja salir hasta conectar. Al verificar Meta arranca la extracción de su histórico con un panel en vivo, reanudable aunque cierre la pestaña, y sin que dos procesos pisen lo mismo. También configura tabs, su negocio y la primera Retro, todo con el control del lado del servidor."],
  [53, "Vista simple por default, kanban para el que quiere más", ["arranque-del-cliente", "board-plan-perro"], 59, 0, 56, 33, "La vista simple por default es el norte del producto ('que te diga qué hacer, no que te abrume') y es de esfuerzo medio-bajo: quick win de sellability. La más alta de mi lote por relación impacto/esfuerzo, arriba de los toques de onboarding (54,55).", "Que el cliente vea por default 3 tareas curadas más experimentos, y el kanban completo quede detrás de un toggle 'Avanzado' que se recuerda por cliente. Hoy no existe la vista simple. Es el norte del producto: que la app te diga qué hacer, no que te abrume."],
  [54, "Mini-onboarding al abrir cada tab (sacarlos del wizard)", ["arranque-del-cliente"], 43, 30, 42, 40, "Sacar tabs del wizard grande baja fricción, pero es refinamiento de UX que no factura directo. Impacto medio, esfuerzo medio; queda debajo de la vista simple (53) que es el norte real y de la extracción nocturna (55) que da valor sin manos.", "Que cada pantalla te guíe la primera vez que la abrís (el email ya lo hace con el dominio) y sacar del wizard grande lo que puede esperar: email, Fathom, VSL y Calendly. Solo Meta y WhatsApp quedan en el arranque obligatorio, así el primer contacto es más liviano."],
  [55, "Extracción que sigue de noche + plantillas por rubro", ["arranque-del-cliente", "cimientos-de-datos", "motor-de-nutricin"], 49, 25, 50, 45, "Que el histórico corra de noche solo evita que el cliente tenga que babysittear la pestaña (valor sin manos), más plantillas por rubro que reducen config. Impacto medio-alto; por encima del mini-onboarding (54) porque destraba autonomía real del arranque.", "Hoy el histórico solo avanza con la pestaña abierta: falta que corra de noche solo. Y terminar la idea de 'menos config': el editor de funnel ya es liviano; falta un banco de plantillas de nutrición por tipo de negocio y resaltar lo que el usuario suele saltear."],
  [56, "Armador de campañas nuevas con MaKo", ["cerrar-el-ciclo", "rplica-de-meta"], 40, 100, 60, 55, "El armador de campañas con MaKo es palanca directa de retorno, pero está al 100%. Alto impacto histórico, no punta; empatado con el navegador de Meta (60) en peso pero abajo por estar hecho.", "Lanzar una campaña con una pregunta por pantalla: creativos, inversión, objetivo, estrategia, público y destino. Con eso MaKo propone la estructura y escribe el copy; vos revisás y publicás en pausa. Lo que decidís vos manda, MaKo solo redacta. Crea la campaña, el conjunto, el anuncio y el creativo, sube los videos e imágenes y soporta Instagram y Threads. El selector de conversión muestra primero el pixel y solo los eventos que están activos."],
  [57, "Salud de la cuenta de Meta + recomendaciones", ["cerrar-el-ciclo", "pulso-diario-vista"], 46, 50, 48, 45, "Que la salud de Meta dé recomendaciones solas y accionables toca plata (cuenta que no entrega = ads muertos), pero es completar un 50% de una vista analítica, no vender MaKo. Medio parejo; debajo del Purchase CAPI (58) que cierra loop de cash.", "Una vista que responde '¿la cuenta está entregando?': estado de pago, resumen de entrega y botón para que MaKo la analice, más una alerta roja en el semáforo si la cuenta está impaga, deshabilitada o con problemas. Meta bloquea sus recomendaciones nativas por el tema de pago, así que las deriva MaKo. Ya está el análisis a pedido y el historial de estados malos; falta que las recomendaciones salgan solas y sean accionables."],
  [58, "Avisarle a Meta cuándo cobrás (Purchase por CAPI)", ["cerrar-el-ciclo", "dashboard-de-analtica"], 63, 60, 58, 42, "Mandar Purchase por CAPI hace que Meta optimice sobre plata cobrada y no sobre agendas: retorno directo del gasto del cliente y ya va al 60%. De lo más alto de mi lote junto con la vista simple (53); le gana a salud (57) por atacar cash real.", "Los eventos de arriba del embudo (lead, lead calificado y agenda) ya se le mandan a Meta por la Conversions API cada vez que se actualiza un lead, venga del webhook, de Fathom o de la carga manual. Falta el evento Purchase al cobrar (cierre o cuota) con el monto real, para que Meta optimice sobre la plata que entra y no solo sobre las agendas. Con control de duplicados y verificado en el panel de eventos de Meta."],
  [59, "Confirmar en vivo que Meta deja crear + pendientes menores", ["cerrar-el-ciclo", "rplica-de-meta"], 43, 0, 40, 30, "Confirmar en vivo que Meta deja CREAR es de-riskear una feature ya casi lista, esfuerzo bajo pero impacto acotado (solo destraba publicar campañas nuevas). Arriba de menores por barato, debajo del Purchase (58) que mueve plata del cliente.", "Riesgo abierto: que MaKo pueda pausar, cambiar presupuesto y renombrar NO garantiza que Meta le deje crear campañas nuevas; ese permiso hay que confirmarlo contra la cuenta real recién al publicar (no se pudo probar la creación de verdad desde el entorno de pruebas). Menores: armar formularios de lead ads desde cero (hoy solo reusa los que ya existen), no duplicar si se reintenta, y manejar videos pesados que tardan en subir."],
  [60, "Navegador estilo Meta + escribir estado/presupuesto/nombre", ["rplica-de-meta", "agente-de-ads"], 40, 100, 62, 58, "El Ads Manager propio con escritura a Meta cierra el loop ver→accionar y ya está probado con 27 campañas: alto impacto, pero hecho. No ocupa punta; por peso empata con el armador (56).", "Tabla ordenable con multiselección, columnas configurables, primera columna fija, encender/apagar y presupuesto editables en la misma fila, estado en vivo + señales + datos del CRM, y detalle por entidad con gráficos. Los cambios llegan a Meta revisando el error real que a veces viene dentro de una respuesta OK, se aplican al instante y se revierten si fallan, solo para el dueño."],
  [61, "Renombrar en lote por plantilla + edición en la fila", ["rplica-de-meta"], 33, 100, 45, 40, "Renombrar en lote por plantilla es prolijidad operativa útil, verificado 26/26 y terminado. Impacto medio-bajo, sin urgencia; zona baja, debajo del navegador de Meta (60) que es la pieza central del Ads Manager.", "Editar el nombre en la misma fila y renombrar en lote con MaKo por PLANTILLA con variables: MaKo solo devuelve las partes con sentido (objetivo, ángulo, etc.) y el nombre se arma con la plantilla. Numeración jerárquica anclada al padre (001 / 001.01 / 001.01.a), mes y año consistentes, y filtro por rango de fecha. Verificado 26 de 26."],
  [62, "Editar público / +anuncio / +conjunto + resumen de problemas", ["rplica-de-meta", "cerrar-el-ciclo"], 33, 100, 45, 45, "Editar público/+anuncio/+conjunto completa la escritura a Meta y está hecho: impacto medio-bajo, sin facturar por sí mismo. Empatada con renombrar (61) en zona baja por ser cola ya cerrada del Ads Manager.", "Los tres cambios por fila (todo en PAUSA): editar el público de un conjunto superponiendo solo lo que tocás (porque Meta reemplaza todo el público si no), agregar un anuncio y agregar un conjunto que hereda del primero. Un anuncio 'con problemas' propaga el aviso hacia su conjunto y su campaña, con un chip clickeable en español y opción de editar los textos. Presupuesto mostrado en dólares."],
  [63, "Armado del contexto + conocimiento recuperado + fases + arranque (hecho)", ["sistema-de-contexto", "tooluse-core-de"], 42, 100, 66, 55, "El armado de contexto es el cimiento para que MaKo no responda genérico (habilita todo el doer), pero está al 100%. Alto impacto foundational, no punta; por encima de sus propias colas (65,66) por peso, abajo por hecho.", "MaKo combina persona + núcleo + perfil + instrucción de la pantalla + conocimiento + datos, y si algo falta usa el prompt de antes sin romperse. El conocimiento se guarda listo para buscar por similitud y se re-indexa solo cuando cambia. Fases por pantalla + wizard de arranque (Oferta/Avatar/Personaje) que extrae los datos con IA."],
  [64, "Prompts editables + conocimiento por cursos + asesor (hecho)", ["sistema-de-contexto", "bandejas-de-whatsapp"], 38, 100, 55, 45, "Prompts editables sin redeploy + conocimiento por cursos ya entregado: impacto medio-alto para iterar barato, pero terminado. Debajo del armado de contexto (63) que es más central; zona baja por hecho.", "Registro central de prompts + guardado de ediciones con historial (30 versiones); pantalla de Configuraciones con los 33 prompts en 10 grupos, con guardar/restaurar/resetear y aviso en los delicados. El conocimiento se organiza por curso/autor/área; semilla del curso 'Levanta Muertos', alta manual y transcripción de audio. El asesor de WhatsApp ya usa esa metodología."],
  [65, "Registrar los prompts de Experimentos/Retro + corregir un cartel", ["sistema-de-contexto", "experimentos-como-fuente", "retro-real-rendicin"], 37, 25, 30, 20, "Registrar los prompts de Experimentos/Retro y corregir un cartel es esfuerzo mínimo pero impacto chico (solo evita un redeploy para retocar). Quick fix barato; empata con features hechas de bajo peso, arriba de los 'lejanos' (66).", "Los prompts de Experimentos y Retro se usan pero no están en la pantalla editable, así que no se pueden retocar sin redeploy: sumarlos al registro. Y en la vista de Contexto el núcleo figura como 'no editable' cuando desde Configuraciones ya sí lo es: corregir el cartel."],
  [66, "Mejorar la búsqueda de conocimiento + curar más cursos", ["sistema-de-contexto", "mako-escribe-la"], 22, 15, 28, 55, "pgvector y curar más cursos es optimización 'a escala' explícitamente lejana, sin cliente que hoy lo pida: impacto bajo, esfuerzo medio-alto. Pulido prematuro; casi al fondo, apenas arriba de los escritores lejanos (51).", "A escala conviene una búsqueda de similitud nativa en la base (pgvector con índices) en vez de traer todo y comparar en memoria. Y activar el área 'ads' para que el conocimiento por área alimente también la generación de creativos, no solo los mensajes; curar y sembrar más cursos. Lejano."],
  [67, "Motor de hipótesis medibles + la regla en el núcleo + 3 vistas (hecho)", ["experimentos-como-fuente", "sistema-de-contexto", "retro-real-rendicin"], 38, 100, 55, 50, "El motor de hipótesis medibles es el único lugar donde MaKo concluye con datos y ya está entregado: impacto medio-alto, pero hecho. Zona baja; por encima de sus colas (68,69) por peso, sin punta por completado.", "Convierte una hipótesis en experimento con línea de base comparable, mide en vivo y da veredicto (validada/refutada/no concluyente) más el aprendizaje; es el único punto donde MaKo concluye. La regla 'hipótesis, no verdades' vive en el núcleo, y al contexto de MaKo solo entran las verdades validadas. Tres vistas (Retro/Experimentos/Conclusiones) con wizard y tarjetas en vivo."],
  [68, "Cerrar experimentos solos + destrabar las ideas", ["experimentos-como-fuente"], 40, 25, 38, 35, "Cerrar experimentos solos al vencer es cierre de loop de mediano valor y esfuerzo contenido (la medición ya es automática). Medio parejo; arriba de pgvector (66) por más útil y barato, debajo de la plata por anuncio (69) que da retorno real.", "La función de cierre ya existe y es segura porque la medición es automática, pero falta el proceso que cierre los experimentos solo al vencer. Además quedó suelto el generador de ideas de experimentos, sin nadie que lo consuma, y los estados propuesto/descartado están muertos en la pantalla."],
  [69, "Plata cobrada por anuncio + histórico de veredictos", ["experimentos-como-fuente", "cerrar-el-ciclo", "dashboard-de-analtica", "retro-real-rendicin"], 50, 0, 55, 50, "Cruzar cada anuncio con pagos da el retorno real por creativo y alimenta Retro, semáforo y agente de ads (hoy razonan sobre proxies de leads): toca plata y destraba varias piezas. De lo más alto sin hacer de mi lote, cerca de la vista simple (53) y el Purchase (58).", "Cruzar cada anuncio con los pagos para tener el retorno real por creativo; hoy solo hay retorno agregado y tanto la Retro como el semáforo razonan sobre proxies (leads). Y guardar la serie de veredictos por anuncio (cuándo se valida uno, cuándo se apaga por quemar plata) que hoy se calcula pero no se persiste, para alimentar los detectores de 'quema de dinero'."],
  [70, "Motor venta vs servicio + análisis profundo (hecho)", ["closing-analyst-analista"], 34, 100, 50, 50, "El motor venta-vs-servicio del Closing Analyst está completo y es un analista de proyecto de baja prioridad: impacto medio, sin facturar directo. Zona baja; por debajo de las piezas de Meta que mueven gasto real.", "Trae y pagina las llamadas de Fathom, matchea por el email del invitado externo, clasifica cada una (venta / entrega de servicio / interna / prueba) y puntúa solo las de venta, guardando fortalezas, debilidades, objeciones, próximo paso y momentos con su cita y su minuto. La grabación queda embebida con salto directo a cada momento."],
  [71, "Puntaje confiable + dos vistas + R1/R2 solo con ventas", ["closing-analyst-analista", "ficha-del-lead"], 32, 100, 45, 40, "El puntaje confiable y el re-vinculado R1/R2 arreglan calidad de dato del Closing, ya terminado: impacto medio-bajo. Analista lejano en prioridad; casi al fondo junto a las colas del Ads Manager (61,62).", "Se arregló el falso puntaje 0: reintenta ante errores de Fathom, la venta sin transcript queda 'pendiente' (no cuenta como 0) y los promedios la excluyen. Vista de Métricas (KPIs, hallazgo de la semana, tendencia, embudo) y vista de Llamadas. Las reuniones que se auto-vinculan al lead usan SOLO las de venta; un script limpió 14 mal vinculadas y re-vinculó 50."],
  [72, "Perfil + campanita + motor de reportes", ["comunicacin-con-el"], 36, 100, 52, 48, "Perfil + campanita + motor de reportes multicanal ya entregado convierte reportes en acción, impacto medio-alto pero hecho. Zona baja; por encima de los analistas (70,71) por ser transversal, sin punta por completado.", "El perfil con sus pestañas y la config de por dónde querés recibir cada reporte, la campanita de avisos dentro de la app, y el motor que arma reportes por hora, día y semana y los manda por WhatsApp o email. Incluye el truco para meterse en la ventana de 24h de WhatsApp: primero una plantilla de apertura y después el texto libre."],
  [73, "Reportes por cada cliente", ["comunicacin-con-el", "multiinquilino-workspace"], 39, 0, 38, 35, "Reportes por cliente es requisito para vender a varios (multi-cliente), pero es plomería de reporte, no genera plata directa; arriba del polish de analistas/board, abajo de las señales de WhatsApp (75) que sí destraban seguimiento.", "Hoy los reportes y los envíos masivos de email salen solo para el dueño de la agencia. Que cada cliente reciba sus propios reportes, por su canal y su contacto."],
  [74, "MaKo responde y ejecuta lo que le pedís por WhatsApp", ["comunicacin-con-el", "bandejas-de-whatsapp"], 30, 10, 35, 55, "Que MaKo ejecute lo que le respondés por WhatsApp es lindo doer pero esfuerzo alto (distinguir dueño/lead) y requiere coordinar con el otro Claude; queda por debajo de 75, que es la señal base más barata y útil.", "Mandarle reportes al dueño ya funciona; falta el camino de vuelta: que MaKo lea lo que el dueño le contesta y ante un 'sí, dale' pause las campañas de verdad y adjunte el PDF. Para eso el sistema tiene que distinguir si el mensaje que entra es del dueño o de un lead (hoy no lo diferencia y eso rompe el ruteo). Lo toca también el otro Claude: hay que coordinar."],
  [75, "Señales de WhatsApp en el lead + toques por lead", ["comunicacin-con-el", "ficha-del-lead"], 47, 20, 48, 40, "Guardar última respuesta/ mensaje por lead destraba el seguimiento automático del que no contesta (el no-show es el asesino del high-ticket): la palanca de plata más concreta de mi lote, por eso la más alta de las tareas vivas de este tramo.", "Guardar en cada lead cuándo respondió por última vez y su último mensaje: eso habilita el seguimiento automático del que no contesta, los tiempos límite y ordenar a quién atender primero. Sumar toques de nutrición individuales, editables desde la ficha. Y mostrar en el chat con qué número del cliente se contactó al lead (la pestaña de teléfonos ya está; falta cruzar la conversación con el número)."],
  [76, "Cuentas reales con rol + login con Google (hecho)", ["cuentas-roles-y", "cerrar-la-auditora"], 30, 100, 30, 20, "Cuentas con rol y login Google: HECHO. Fue habilitador del multi-cliente, pero al estar entregado no ocupa punta; score medio-bajo acorde a impacto pasado.", "Se reemplazó la contraseña compartida por cuentas de verdad: cada persona entra con su Google, con rol y estado (invitado, activo o suspendido), sesión firmada y credenciales cifradas. En cada pedido el sistema revisa contra la base quién es y si sigue habilitado."],
  [77, "Cargar los tokens de cada integración con tutorial (hecho)", ["cuentas-roles-y"], 28, 100, 28, 20, "Carga de tokens con tutorial: HECHO. Útil para onboarding pero ya cerrado; queda en baja como el resto de lo entregado de infraestructura de cuentas.", "Un asistente para el admin donde cada servicio tiene su paso a paso para conseguir el token, un botón para probar la conexión y guardado cifrado. Al arrancar, la app hidrata las credenciales guardadas; lo que cargás desde la app siempre manda."],
  [78, "Roles por cliente (admin/closer/setter) + alta en un paso", ["cuentas-roles-y", "multiinquilino-workspace"], 34, 100, 40, 25, "Roles por cliente + alta en un paso: HECHO. Más impacto que 76/77 porque habilita vender a clientes con equipo, pero entregado, así que no sube a la punta.", "Cada cliente tiene sus roles: admin-cliente, closer y setter, y cada uno ve solo sus pantallas. Dar de alta un cliente crea su workspace y su admin de una; desde /equipo se invita a closers y setters. El control es real del lado del servidor, no solo esconder botones del menú."],
  [79, "Vista General 'tu norte' + bloque Hoy", ["dashboard-de-analtica", "pulso-diario-vista"], 42, 100, 55, 30, "Vista General 'tu norte' + Hoy: HECHO. Es el núcleo del producto vendible y lo primero que se muestra en demo; alto impacto histórico, pero al estar cerrado se ubica en la franja media-alta de lo entregado.", "El objetivo global con su ritmo y su fecha estimada de llegada como lo primero que ves, un bloque 'Hoy' con las juntas del día y la cola de acción, la inversión por anuncio, y que desde cualquier total puedas bajar hasta los nombres de los leads. Es la pantalla que contesta '¿voy bien?' de un vistazo."],
  [80, "Marketing: CAC/ROAS + tendencias + anuncios ganadores", ["dashboard-de-analtica", "agente-de-ads"], 42, 100, 55, 30, "Marketing CAC/ROAS + ganadores: HECHO. Igual de central que 79 para mostrar y cobrar; entregado, así que comparte franja media-alta sin ocupar el pico reservado a lo vivo que acerca el go-live.", "CAC como número grande global, semanal y mensual, ROAS, resumen de la cuenta, tendencias en un gráfico grande con selector de métrica y varias series, y los anuncios ganadores (top 5 + ranking) con veredicto claro: validar si ya trajo 10+ leads, apagar si quemó 80 dólares sin ninguno. Con preview del creativo."],
  [81, "Comercial + Plata/Cobranza", ["dashboard-de-analtica"], 39, 100, 48, 30, "Comercial + Plata/Cobranza: HECHO. Muy vendible (muestra plata) pero cerrado; apenas por debajo de 79/80 por ser vista de soporte más que el 'norte'.", "Comercial con cohortes, el ciclo de venta por tramos con su línea de tiempo, el no-show por cohorte e ingresos contra gasto. Plata con vendido/cobrado/por cobrar (mirando hacia adelante por fecha de vencimiento), plan de pagos en cuotas, el contrato firmado leído por IA que autocompleta el plan, y 'a quién cobrarle' con marcar cobrado y deshacer."],
  [82, "Cada número clickeable → desglose por lead + filtro de fecha + mobile", ["dashboard-de-analtica"], 37, 100, 42, 25, "Números clickeables + fecha + mobile: HECHO. Patrón transversal que hace auditable el tablero; entregado y de impacto algo menor que las vistas núcleo, franja media.", "El patrón en toda la app: tocás un número y se abre el desglose con los leads que lo componen (cohortes, tramos, vendido/cobrado). Un filtro de fecha global que se mantiene mientras navegás, todas las fechas en formato día/mes/año, y la app usable en el celular. Es lo que hace el tablero auditable hasta el nombre."],
  [83, "Conector de Meta Ads (rendimiento + presupuestos + histórico)", ["cimientos-de-datos"], 40, 100, 55, 35, "Conector Meta Ads: HECHO. Columna vertebral del dato sobre el que todo razona; sin él no hay producto, pero entregado, por eso franja media-alta y no punta.", "Meta a nivel de cada anuncio, los presupuestos diarios de los conjuntos de anuncios, la carga del histórico completo de rendimiento y un repaso diario de leads como red de seguridad. Es la columna vertebral del gasto y la performance."],
  [84, "Agendas y formularios que entran solos (Calendly + Meta)", ["cimientos-de-datos"], 38, 100, 50, 30, "Calendly + Meta Lead Ads que entran solos: HECHO. Captura de agendas/formularios, cimiento clave ya cerrado; medio-alto por impacto pasado, sin urgencia.", "El webhook de Calendly que da de alta el lead solo, con sus UTMs y las cuatro respuestas del formulario; la carga del histórico de Calendly como leads; y el webhook de Meta Lead Ads cruzando por teléfono. Cierra la captura de agendas y formularios desde las dos puntas."],
  [85, "CAPI: devolverle a Meta las conversiones de arriba del embudo", ["cimientos-de-datos", "cerrar-el-ciclo"], 34, 100, 40, 30, "CAPI de arriba del embudo: HECHO. Mejora optimización de Meta pero el Purchase (el que más mueve) vive en otro proyecto; entregado, franja media.", "La base para mandarle a Meta los eventos de conversión (Lead, Lead Calificado y Agenda) por su API de conversiones, para que optimice mejor las campañas. El evento de Compra al cobrar queda pendiente y vive en el proyecto de cerrar el ciclo con Meta."],
  [86, "Las fuentes del VSL: YouTube + Panda", ["cimientos-de-datos"], 33, 100, 35, 30, "Fuentes VSL (YouTube+Panda): HECHO. Habilita retención y etapa VSL, soporte del dato; cerrado y de impacto acotado, franja media-baja de lo entregado.", "YouTube por su API de analítica (no acumulado), una serie continua que incluye el VSL anterior, y Panda como fuente del VSL actual con su tarjeta en Marketing. Habilita las curvas de retención y la etapa VSL del embudo."],
  [87, "Separar lo estable de lo vivo + Patrones + Cuadrante (hecho)", ["ads-analyst-analista", "rplica-de-meta"], 29, 100, 30, 30, "Ads Analyst estable/vivo + Patrones + Cuadrante: HECHO. Analista de guiones, proyecto de baja prioridad y lejano a facturar; entregado, va abajo.", "La lectura del guion se guarda sin métricas, así no envejece; las métricas se agregan por anuncio sin filtro de fecha (gasto, hook rate, retención por tramos, agendas, cierres, veredicto). Los Patrones se calculan con umbrales y el Cuadrante quedó calibrado con ejes y umbrales fijos."],
  [88, "Valorar un guion nuevo + taxonomía + imágenes + detalle unificado", ["ads-analyst-analista", "rplica-de-meta"], 29, 100, 30, 35, "Valorar guion nuevo + taxonomía + OCR: HECHO. Feature rica pero de un analista de prioridad baja; cerrada, se queda en baja junto a 87.", "Pegás un guion nuevo y MaKo lo compara contra el perfil de la cuenta: lo clasifica, dice qué patrones cumple y cuáles pierde, predice el veredicto y propone reescrituras, guardando el historial. Taxonomía de ángulos/avatares editable compartida con el arranque + override por anuncio. Imágenes leídas por OCR. Detalle unificado (Rendimiento/Audiencia/Guion) reusado por el Ads Manager."],
  [89, "Limpiar código muerto + tablero por veredicto", ["ads-analyst-analista"], 6, 0, 12, 25, "Limpiar código muerto + kanban por veredicto del Ads Analyst: casi cero plata, proyecto de baja prioridad y ni siquiera destraba nada; lo más abajo de mi lote.", "Borrar dos componentes viejos que quedaron huérfanos: el administrador de ángulos anterior y un navegador de anuncios que ya no se usa. Y una idea pendiente: un tablero tipo kanban, alternativo al cuadrante, agrupado por veredicto (Escalar / Reescribir / Mejorar / Repensar)."],
  [90, "Rebuild a /plan (Trello) + Perro Guardián", ["board-plan-perro"], 26, 100, 28, 40, "Rebuild /plan + Perro Guardián: HECHO. Herramienta interna de planificación, no factura; entregada, franja baja.", "Tablero tipo Trello que se adapta al rol: columnas de prioridad, arrastrar y soltar, checklists que derivan el avance, proyectos editables, filtros, deshacer, confirmaciones e historial de cambios, con un mismo componente para agencia y cliente. El Perro Guardián prioriza, propone re-priorizar, fija un objetivo principal, debate cada tarea, cuida la pirámide y ordena los proyectos del 1 al 10 sin empates."],
  [91, "Sacar tareas de reuniones + poblar el tablero (hecho)", ["board-plan-perro", "closing-analyst-analista"], 25, 100, 26, 30, "Sacar tareas de Fathom + poblar tablero: HECHO. Utilitario interno ya cerrado; baja prioridad por no acercar venta.", "Extraer tareas del plan directamente desde una reunión de Fathom. Proyectos y tareas de arranque para clientes nuevos (tablero 'Ambos' con las que ya hizo Mauricio). Poblado con todo el roadmap sacado de la memoria (123 tareas)."],
  [92, "Cerrar pendientes de desarrollo del tablero", ["board-plan-perro"], 18, 10, 20, 30, "Cerrar pendientes de dev del tablero (sacar modo prueba, migración de motivo/deadline): polish interno de un proyecto de baja prioridad, no mueve plata; queda abajo, apenas arriba de 89 por ser deuda que conviene cerrar.", "Sacar el modo de prueba que permite saltearse el debate del Perro Guardián, cuando se cierre el desarrollo. Guardar de verdad el motivo del puntaje y el deadline del tablero del cliente (hoy viven solo en memoria, falta migración). Y que la extracción desde Fathom use la cuenta de cada cliente en vez de la de la agencia."],
  [93, "Tablero con look nuevo + sidebar plegable", ["reskin-de-la"], 41, 80, 42, 35, "Reskin del tablero + sidebar plegable: al 80% y alineado a la landing, deja la app presentable para demo/venta (una app despareja frena que la usen y compren); es el reskin que más ayuda a mostrar, por eso el más alto de la franja de pulido.", "El tablero de marketing pasado al tema claro en sus 8 pantallas con la interactividad de vuelta, alineado al look de la landing, con el ícono propio de la app y las pantallas portadas del diseño (funnel, closing, Retro). El sidebar se pliega a un riel que se abre al pasar el mouse, con los grupos y el perfil en menús laterales. Falta cerrar los analistas, experimentos, el perfil y el onboarding."],
  [94, "Identidad MaKo (logo, voz, análisis en cada gráfico)", ["reskin-de-la"], 29, 80, 30, 25, "Identidad MaKo (logo, voz, ✦ en gráficos): al 80%, aporta consistencia de marca para vender pero es más cosmético que 93; esfuerzo bajo, impacto medio, franja media.", "El logo y la marca de MaKo, la voz rioplatense y el modelo de IA que ajusta el esfuerzo según la tarea. Cada gráfico lleva al lado un análisis de MaKo con su propio historial y sus sesiones. Falta ponerle ese ✦ a los gráficos que todavía no lo tienen y borrar el logo viejo que quedó dando vueltas."],
  [95, "Desplegables propios + textos R1/R2 + admin de eventos", ["reskin-de-la"], 27, 50, 22, 30, "Desplegables propios + textos R1/R2 + admin de eventos: pulido fino al 50%, poco impacto en facturar; por debajo de 93/94 dentro del reskin.", "Usar el desplegable propio en toda la app, nunca el nativo pelado; quedan un par de pantallas viejas por migrar. Los nombres de reuniones ya están casi todos como R1/R2; faltan dos lugares, y ahí se cambia solo el texto que se ve, nunca las claves internas. Y un administrador de eventos que no arrancó."],
  [96, "Landing /vsl + realce del CTA", ["landing-de-venta"], 47, 100, 50, 30, "Landing /vsl + realce del CTA: es la cara de venta (proyecto top), pero está HECHA al 100%; por eso score medio-alto sin ocupar el pico —el cuello real de vender no es esta tarea sino pegar el tracking y armar el flujo, que viven en otras tareas.", "La landing armada desde el diseño (no HTML a mano) con toda su interactividad de vuelta: carruseles, video, Calendly embebido, animaciones. Responsive para celular y el CTA reforzado con escasez honesta, la oferta y micro-señales de confianza, todo sin tocar el diseño original."],
  [97, "Identificar al espectador anónimo del VSL", ["landing-de-venta", "cimientos-de-datos"], 40, 100, 70, 40, "El bautismo del anónimo del VSL es motor de venta puro (identifica al tráfico), pero está al 100%: alto impacto histórico, ya cobrado, no ocupa lugar arriba como el 98 que sí falta.", "Tres caminos para convertir un ID anónimo en un lead con nombre: el directo (viene con el ID del lead en el link y queda estampado al instante) y dos por Calendly. Todo el comportamiento fino del VSL (cuánto retiene, cuántos VSL vio) queda colgado de ese ID. El grabado anónimo funciona bien; el cuello es el bautismo, o sea ponerle nombre al anónimo."],
  [98, "Pegar el código en la landing + flujo de WhatsApp (depende de Martín)", ["landing-de-venta"], 91, 0, 88, 25, "La estrella del lote: cierra el camino directo de atribución del VSL por donde entra el grueso del tráfico, y es casi todo pegar el código + armar el flujo de WhatsApp. Alto impacto sobre la venta y bajo esfuerzo: quick-win que le gana a todo lo demás del rango.", "El instructivo está listo: sumarle al seguimiento la URL y el título del VSL, y leer el ID del lead en todos los eventos. Falta que Martín lo pegue en la landing con el dominio real y arme el flujo de WhatsApp que mande el link con el ID del lead, que es por donde entra el grueso del tráfico y cierra el camino directo."],
  [99, "15 páginas de detalle + completar los huecos", ["landing-de-venta"], 61, 40, 58, 45, "Las páginas de detalle venden funcionalidad y suben conversión, por eso pesa más que los analistas; pero es contenido/pulido que completa Martín, así que va debajo del 98 y no en la punta.", "Las 15 páginas de detalle por funcionalidad (con sus testimonios), públicas, con el estilo de VSL y los links 'Saber más' inyectados. Faltan las capturas y demos de cada una, llenar los testimonios, y que las tarjetas del grid de arriba lleven a la página de detalle en vez de a un ancla. El contenido lo completa Martín."],
  [100, "11 recetas del repo + públicas seleccionadas", ["skills-de-claude"], 20, 100, 30, 30, "Mapa del código: herramienta de dev útil pero no acerca un peso a la venta, y encima ya está al 100%. Muy por debajo de cualquier tarea de landing o ads.", "Once recetas a medida del código: cuatro base (consultas seguras por cliente, migraciones numeradas, convenciones de la app, prompts editables) y siete que tapan huecos concretos (auditar fugas entre clientes, armar tareas programadas, conectar servicios nuevos, recibir webhooks, chequear prompts, y armar analistas y writers de MaKo). Más algunas públicas elegidas sin pisar las que ya vienen de fábrica."],
  [101, "Mapa navegable del código (Graphify)", ["skills-de-claude"], 20, 100, 30, 35, "Recetas del repo ya hechas: aceleran construir pero no facturan; mismo pelotón bajo que el 100 y el 102, lejos de las palancas de plata.", "Después de probar que una opción no servía para este código, Graphify sí: arma un mapa de quién llama a qué a lo largo de todo el proyecto (miles de conexiones, con archivo y línea). Subido con su receta, la regla en la documentación del repo y un visor dentro del panel de super-admin."],
  [102, "Gasto de IA por operación + saldo a mano", ["skills-de-claude"], 18, 100, 28, 30, "Medir el gasto de IA es higiene interna, no ingreso; ya está completo. De los más abajo del lote junto con infra y copiloto.", "Registro de cuántos tokens y cuánta plata gasta cada operación de IA por modelo, y un chip 'Saldo IA' en el sidebar que muestra lo que queda (saldo cargado menos gasto, porque la API de Anthropic no da el saldo prepago), el gasto de cada operación al instante y el historial con el motivo en criollo."],
  [103, "Usar las recetas como hábito", ["skills-de-claude"], 24, 25, 30, 25, "Volver hábito las recetas es proceso, no plata; esfuerzo bajo pero impacto casi nulo sobre la venta, apenas arriba del 100/101 por estar pendiente.", "Las recetas están instaladas pero falta usarlas siempre al construir (evitar fugas entre clientes, numerar bien las migraciones, no dejar prompts desincronizados) y volverlo un hábito documentado. Incluye chequear de forma sistemática que cada migración subida esté realmente aplicada en producción, algo que ya falló caro una vez."],
  [104, "Guardar el histórico de veredictos por anuncio", ["agente-de-ads", "dashboard-de-analtica"], 48, 20, 50, 30, "Guardar el histórico de veredictos es cimiento barato que destraba los detectores de quema del agente de ads; menos esfuerzo que el 105 y lo habilita, por eso queda arriba dentro de ads aunque solo no facture.", "Hoy el veredicto de cada anuncio (validar o apagar) se calcula al vuelo y no se guarda, así que no hay forma de detectar 'lleva N días quemando plata'. Guardar una foto diaria destraba los detectores de quema en el tiempo."],
  [105, "Reglas de presupuesto según la plata real", ["agente-de-ads", "cerrar-el-ciclo"], 56, 0, 62, 60, "Subir/recortar presupuesto según plata cobrada es la palanca de ROI más directa de ads, pero depende del cruce plata×anuncio y tiene esfuerzo real; importante y por encima del 106, debajo del 98/99 que tocan la venta del propio MaKo.", "Subirle a los que venden y recortarle a los que no, según la plata cobrada atribuida a cada anuncio (el cruce de gasto × leads × pagos), no solo por cuántos leads trajo. Incluye duplicar el ganador. Es la apuesta central una vez que la plata por anuncio está calculada."],
  [106, "Ejecutar con tu OK + rastro", ["agente-de-ads", "rplica-de-meta"], 45, 10, 50, 45, "La capa de ejecutar-con-OK cierra el loop de ads pero depende del 105 para tener qué ejecutar; medio, apenas debajo de las reglas que la alimentan.", "Proponer cada cambio de presupuesto o estado y aplicarlo recién con tu confirmación, dejando rastro de quién lo hizo y por qué. La IA propone, vos decidís, y queda registrado."],
  [107, "Analizar las llamadas de entrega en vez de tirarlas", ["cs-analyst-analista", "closing-analyst-analista"], 36, 0, 42, 35, "CS Analyst reusa la infra del Closing y es barato, pero es un analista nuevo que no acelera la venta de MaKo; queda medio-bajo, arriba de sus propios dependientes 108/109 por ser el que los habilita.", "Hoy las llamadas de entrega del servicio se transcriben y se descartan. Correrles el mismo analista que usamos para las de venta (resumen, riesgos, próximos pasos) y cargar el histórico ya transcripto. El costo extra es casi cero porque la transcripción ya se hace igual."],
  [108, "Termómetro de baja por cliente", ["cs-analyst-analista"], 28, 0, 38, 45, "Termómetro de baja depende del 107 y suma esfuerzo; retención es valiosa pero lejana a facturar ya, va debajo del análisis que la alimenta.", "Un termómetro por cada cliente activo que combina el ánimo de su última llamada de servicio con la cuota impaga y otras señales, para ordenar a quién retener primero. Cálculo directo donde se pueda, IA solo para leer el ánimo."],
  [109, "Vista de cartera + alertas de baja al dueño", ["cs-analyst-analista", "comunicacin-con-el"], 27, 0, 38, 45, "Vista de cartera + alertas cierra el loop de CS pero es la última pata de un proyecto de baja prioridad; abajo, apenas por debajo del 108.", "Una vista de la cartera con semáforo de riesgo y alertas de baja que le llegan al dueño por campanita o WhatsApp con la acción sugerida. Cierra el loop: no solo detecta, avisa y propone qué hacer."],
  [110, "Oferta por niveles + un anuncio por funcionalidad", ["growth-vender-mako", "landing-de-venta"], 38, 0, 45, 40, "Definir oferta por niveles es barato y sí toca la venta de MaKo, por eso lo pongo por encima del resto de growth; pero vender el producto a medio hacer quema pólvora, así que no sube más.", "Venderle a todo el que corra un VSL Funnel, con planes por nivel que desbloquean según la situación del cliente (definir los niveles y qué abre cada uno). Modelo Claudio Conde (vender caro con una sola funcionalidad): producir muchos anuncios, cada uno vendiendo una sola cosa que hace MaKo."],
  [111, "Página de gracias + testimonios + demos + costos", ["growth-vender-mako", "landing-de-venta"], 26, 0, 30, 45, "Página de gracias, testimonios y demos es colateral de marketing 'para cuando vuelva a Buenos Aires'; pulido de growth, debajo del 110 que al menos define la oferta.", "La página post-agenda que obliga a preparar la llamada o la cancela, juntar y mostrar testimonios reales, un Loom de demo por funcionalidad, y sumar a la landing tarjetas de funcionalidades que ya existen pero no figuran (revenue y cobranza, vista general, contrato leído por IA, pendientes). Más el costo interno y por cliente y un mapa de uso. Para cuando vuelva a Buenos Aires."],
  [112, "Cuentas propias por cliente + plan pago", ["infraestructura-propia-e", "multiinquilino-workspace"], 16, 20, 28, 45, "Cuentas propias por cliente es problema de escala que hoy nada frena; sin clientes pagando no mueve la aguja, va abajo con el resto de infra.", "La cuenta gratis de email da 3.000 por mes y 100 por día, y con una sola cuenta para todos los clientes eso se topa rápido: al escalar hace falta el plan pago y una cuenta propia por cliente para el email y el WhatsApp no oficial (la puerta ya está prevista en las credenciales). Habilita el volumen sin chocar con los límites de envío."],
  [113, "Pasar cuentas a nombre propio + dominio + método de actualización", ["infraestructura-propia-e", "landing-de-venta"], 8, 0, 25, 60, "Migrar base/hosting/dominio a nombre propio es fondo caro y explícitamente 'no prioridad hasta que haya clientes pagando'; de los más abajo del lote.", "Mover la base de datos, el hosting y el dominio de Mauricio a cuentas propias y servir la landing desde la raíz de un dominio propio. Definir cómo ir mejorando sin cortarle a los que están probando (activar cosas por cliente, un registro de cambios, probar antes de exponer); hoy todo va directo a producción. No es prioridad hasta que haya clientes pagando."],
  [114, "Bot que contiene el tráfico frío + que el lead escriba primero", ["canales-fros-bot", "bandejas-de-whatsapp"], 14, 0, 28, 60, "Bot de tráfico frío es de arranque lejano y depende de que el resto ya funcione solo; alto esfuerzo, impacto diferido, fondo del pelotón.", "El tercer número del esquema: un bot en la línea oficial que recibe a la gente que llega fría desde los ads, la califica con plantillas y la pasa al número de venta ya tibia. Sumado al patrón de que escriba primero (links de WhatsApp con palabra clave y QR en vivo), que baja el riesgo de baneo alrededor del 90%."],
  [115, "Instagram y mail del lead en la bandeja única", ["canales-fros-bot", "bandejas-de-whatsapp"], 10, 0, 25, 50, "IG y mail en la bandeja única suma canales que hoy nadie reclama; lejano y sin urgencia de plata, junto al bot en lo más bajo.", "Instagram hoy es una pantalla vacía de 'próximamente': traer los DMs de IG a la bandeja unificada. Y un buzón de mail por lead: hoy el mail sirve solo para nutrición y envíos masivos, y el botón de la ficha abre el cliente de correo. Falta ver la conversación y el historial de mails dentro de la ficha."],
  [116, "Investigar la transcripción en vivo", ["copiloto-en-vivo"], 4, 0, 20, 40, "Investigar transcripción en vivo es el arranque de un moonshot (copiloto), el proyecto de menor prioridad; pura exploración sin retorno cercano.", "Evaluar proveedores de transcripción en tiempo real, medir la demora real y el costo por llamada, y ver si es viable montarlo sobre lo que ya tenemos sin arruinar la experiencia del closer."],
  [117, "Sugerencias al closer en tiempo real", ["copiloto-en-vivo", "closing-analyst-analista"], 2, 0, 22, 80, "El copiloto en vivo es el sueño más lejano y caro, choca con algo que ni existe en el stack; máximo esfuerzo, retorno remoto: el piso del lote.", "Detectar las objeciones mientras pasan y sugerir cómo manejarlas desde el cerebro de closing y copywriting, en una interfaz discreta que no distraiga al closer durante la reunión."],
  // ── Tanda "Hola MaKo" + seguridad + costos de IA (julio 2026) ──────────────────
  [118, "Hola MaKo: escuchar en el grupo y actuar con confirmación", ["tooluse-core-de", "comunicacin-con-el"], 92, 100, 90, 40, "El doer dejó de solo leer: el dueño le habla por WhatsApp y MaKo ACTÚA (propone → confirmás → hace). Es la cara conversacional del cerebro que actúa, probada en vivo.", "MaKo escucha en su grupo de WhatsApp y responde con datos reales. Cuando le pedís una acción (cambiar la etapa de un lead, activar/pausar una nutrición, renombrar/pausar una campaña de Meta) NO la ejecuta sola: la deja pendiente con vencimiento y pide un 'sí'; recién ahí la aplica por los caminos ya gateados. Probado: lectura, propuesta, confirmación y cambio de etapa de un lead real revertido."],
  [119, "MaKo recuerda la conversación (memoria por grupo)", ["tooluse-core-de", "comunicacin-con-el"], 80, 100, 78, 20, "Sin memoria, MaKo arrancaba de cero en cada mensaje y pedía datos que ya le habías dado. Ahora la charla tiene hilo, como cualquier IA.", "Cada turno (tuyo y de MaKo) se guarda por grupo y se re-inyecta como historial en cada respuesta. Probado: recordó un dato de un mensaje anterior. Scopeado por cliente."],
  [120, "MaKo entiende audio, imágenes y PDF", ["comunicacin-con-el", "bandejas-de-whatsapp"], 78, 100, 76, 35, "Una IA de verdad recibe notas de voz, capturas y documentos. Ahora MaKo también.", "Las notas de voz se transcriben (español) y se tratan igual que texto; las imágenes (capturas/fotos) y los PDF los lee nativo con visión. Probado: transcribió una nota real y analizó una captura con métricas."],
  [121, "Aislamiento del doer: cada cliente ve solo lo suyo", ["cerrar-la-auditora", "multiinquilino-workspace"], 88, 100, 92, 30, "Riesgo grave tapado: el doer resolvía los datos por la LÍNEA (la voz es el número del dueño), así un grupo de cliente habría traído datos de Mauricio. Ahora el workspace lo decide QUIÉN posee el grupo.", "El doer scopea los datos al workspace dueño del grupo (su mako.grupo_jid), no a la instancia. Grupo de cliente → su data; grupo del dueño → dueño; desconocido → no contesta. Control operativo en la agencia, datos por cliente. Las acciones de Meta siguen gateadas a la cuenta principal."],
  [122, "Historial de tokens: todo el gasto de IA con detalle", ["skills-de-claude"], 62, 100, 55, 25, "Antes solo se veía un slug ('mako-doer-in'). Ahora se registra TODO (Claude, Groq, OpenAI, STT) con proveedor, modelo y motivo legible; el saldo de Claude no se contamina con el gasto barato.", "Cada operación de IA queda en el historial con proveedor + modelo + descripción. El chip Saldo IA muestra 'Últimos movimientos'. Solo el gasto de Claude descuenta del saldo prepago."],
  [123, "IA barata (Groq) + ruteo por tarea", ["skills-de-claude"], 58, 70, 62, 45, "Sacar de Claude Opus lo que no necesita su cabeza (títulos, clasificar, extraer) y el STT baja el costo enormemente. La capa ya existe; falta migrar tarea por tarea midiendo calidad.", "Capa chatCheap/transcribirAudio (Groq gpt-oss-20b + Whisper, no entrena con tus datos; OpenAI de fallback). Audit de los 55 usos de IA: 30 se quedan en Opus (razonamiento/voz de marca/PII), 14 pasan a Groq, 9 STT. Muchos ya cambian con solo la key; falta la migración A/B del resto."],
  [124, "Reuniones miran la HORA + Fathom se auto-adjunta", ["crm-automtico-leads", "recordatorios-de-juntas"], 66, 80, 70, 30, "El CRM trataba una reunión de HOY como futura hasta medianoche (solo miraba el día): decía 'hoy tenés la llamada' cuando ya pasó y no pedía el Fathom. Arreglado.", "Ahora usa junta_N_at (hora real) + 1h de gracia: 'Tus reuniones' muestra 'pasó' y 'Datos sin marcar' pide el Fathom. El cron diario engancha sola la grabación de Fathom al lead (sin depender del webhook). Falta prender CRM_AUTO_ENABLED para el auto-resolve completo."],
  [125, "Zona horaria por workspace", ["arranque-del-cliente", "funnel-como-fuente"], 40, 100, 35, 15, "Todo estaba clavado a Tijuana; con multi-cliente cada uno puede estar en otra zona. Base lista.", "tzDeWorkspace(ws) resuelve la zona por cliente (setting mako.timezone). Se corrigió el texto de los disparadores que afirmaban una hora fija equivocada."],
  [126, "Ventana / modo libre del doer + 'escribiendo…'", ["comunicacin-con-el"], 55, 100, 50, 20, "Pedías que no haga falta repetir 'Hola MaKo' todo el tiempo y que se note que está trabajando. Hecho.", "Por grupo: modo 'libre' (responde a todo — default, los grupos son 100% para MaKo) o 'ventana' (el activador abre 15' de charla libre). Muestra 'escribiendo…' mientras razona."],
  [127, "Buscador en la tab Proyectos", ["board-plan-perro"], 22, 100, 20, 5, "Faltaba la barra de búsqueda que sí tiene el Kanban. Agregada (aplica a dueño y clientes).", "Filtra proyectos por nombre y detalle; con búsqueda activa muestra todos los resultados, sin el tope de 8."],
  // ── Pendientes que salieron de esta tanda ─────────────────────────────────────
  [128, "Editor de flujos de MaKo (disparador + pasos)", ["comunicacin-con-el", "recordatorios-de-juntas"], 60, 0, 65, 55, "Que el dueño edite CUÁNDO y CÓMO dispara cada automatización (el 'flujo') y sus pasos, sin tocar código. Diseñado, falta construir.", "Extender las plantillas de aviso a un FLUJO editable: disparador (evento/cron/umbral/manual), pasos editables (mensaje/acción/esperar) y agregar pasos para secuencias multi-mensaje o con PDF. Reusa el choke point de avisos + la cola de confirmaciones."],
  [129, "Rutas propias para cada entidad (deep links finos)", ["tooluse-core-de", "reskin-de-la"], 48, 0, 55, 50, "Hoy MaKo linkea a la TAB pero no a la ENTIDAD: no hay ruta para una llamada analizada, un anuncio ganador, una Retro, una tarea o proyecto puntual. Sin eso, los deep links quedan a mitad de camino.", "Auditar qué vive en sub-tabs sin ruta propia y darle a cada una una URL directa (una llamada de Closing, un experimento/Retro, un anuncio ganador, una tarea del kanban), para que MaKo y cualquier link compartido abran exactamente eso."],
  [130, "Tab SuperAdmin: modelo de IA por tarea (editable)", ["skills-de-claude"], 45, 0, 45, 35, "Ver y editar qué modelo/IA usa cada tarea de la app y poder cambiarlo desde una pantalla — para gobernar el costo sin tocar código.", "Una tab en SuperAdmin que lista los ~55 usos de IA (tarea, modelo actual, proveedor, costo) y deja elegir el modelo/IA de cada uno (Claude / Groq / OpenAI), con la recomendación del audit como sugerencia."],
  [131, "MaKo App Mobile", ["mako-app-mobile"], 41, 0, 58, 72, "Que el cliente vea y actúe desde el celular. Va después del go-live; no todas las pantallas van a mobile y las que van se re-adaptan.", "App móvil (PWA o nativa) con las vistas de consumo rápido + acción de 1 toque (Hoy, chat con MaKo, notificaciones, ficha en lectura, aprobar propuestas); el trabajo denso (Ads Manager, Retro, funnel, analistas) se queda en desktop."],

  // ── Grandes tareas para finalizar (16/7) ────────────────────────────────────
  // Los 7 bloques que dictó Martín, priorizados. La fecha dura manda: Leila y
  // Leandro entran el viernes 17/7. Dos ajustes conscientes a la lista original:
  // (a) "Retro ⇄ Plan ⇄ WhatsApp" figuraba en DOS bloques (Retro 6 y Plan 1) —
  // acá es UNA tarea (#154), porque es un solo build; (b) "Versionado" venía como
  // un párrafo y son tres piezas separables (#140-142).

  // Oferta CEBOLLA — el único bloque con fecha
  [132, "Definir qué capa de la CEBOLLA se vende YA y qué queda para después", ["oferta-cebolla"], 99, 0, 95, 8, "El primer dominó de todo el tablero, y no es código: son 30 minutos de decisión tuya. De acá sale si el trabajo del viernes son 4 horas o 4 días, porque define qué tienen que ver Leila y Leandro cuando entren. Todo lo demás de esta lista espera esta definición.", "Escribir, en una hoja, qué incluye la capa que se vende HOY (¿la vista SIMPLE + Retro + Plan? ¿el CRM? ¿MaKo en WhatsApp?) y qué queda explícitamente afuera para una capa posterior. Regla: si algo no está listo para que un cliente lo toque solo el viernes, no está en la capa de hoy. Sirve de contrato: lo que quede afuera no se toca esta semana por más tentador que sea."],
  [133, "Que Leila y Leandro puedan entrar como clientes antes del viernes", ["oferta-cebolla", "arranque-del-cliente"], 98, 0, 96, 35, "La ÚNICA fecha dura de toda la lista (viernes 17/7) y la única tarea que no se puede correr un día. Es también la prueba de fuego del multi-cliente: pasan de 1 cliente real a 3. Todo lo demás de este tablero puede esperar; esto no.", "Crear el workspace de cada uno, su admin, conectar lo mínimo de la capa que se vende (según #132) y que entren y vean SUS datos, no los de Mauricio. Se apoya en el multi-cliente que ya está en prod. El riesgo real no es técnico: es que se estrene el onboarding con ellos en vivo (por eso #138 va antes)."],
  [134, "Que un usuario pueda entrar como cliente de otra oferta", ["oferta-cebolla", "multiinquilino-workspace"], 90, 0, 80, 30, "Es lo que hace que la cebolla sea una cebolla y no tres productos distintos: un cliente entra por una capa y después cambia de capa sin rehacer nada. Sin esto, cada oferta nueva es un fork.", "Que la oferta/capa sea un atributo del cliente y no una rama del código: entrar como cliente de otra oferta, cambiar de capa, y que las pantallas y el onboarding se acomoden solos a lo que compró. Se apoya en los roles por workspace que ya existen."],
  [135, "Pensar el onboarding de cada tipo de cliente", ["oferta-cebolla", "arranque-del-cliente"], 88, 0, 78, 25, "Cada capa de la cebolla necesita un arranque distinto: pedirle a un cliente de la capa básica que conecte Meta es perderlo en el primer paso. Depende de #132 y define el trabajo de #136.", "Para cada tipo de cliente: qué se le pide, en qué orden, qué se le puede saltear y qué se le rellena solo. Aplica el principio de siempre: primero defaults, después plantillas y sugerencias, y recién al final config a mano. El de la capa más chica debería llegar a productivo sin conectar nada."],

  // Onboarding — el vehículo de la fecha dura
  [136, "Onboarding simple y modular (implementarlo)", ["arranque-del-cliente", "oferta-cebolla"], 92, 0, 85, 40, "Es el vehículo concreto del viernes: sin esto, meter a Leila y Leandro es a mano y no escala al cuarto cliente. Modular porque cada capa de la cebolla enciende distintos módulos (#135); simple porque el wizard actual bloquea de más.", "Convertir el wizard bloqueante actual en módulos que se prenden según la capa que compró el cliente, cada uno salteable si no aplica. Lo que ya existe (integraciones → extracción histórica → tabs → negocio → Retro) pasa a ser un módulo cada uno en vez de un tren que hay que tomar entero."],
  [138, "Probar el onboarding con un cliente de prueba (ANTES que entre Leila)", ["arranque-del-cliente", "oferta-cebolla"], 91, 0, 75, 12, "La póliza de seguro más barata de la lista: media hora de prueba contra el papelón de estrenar el arranque en vivo con una clienta de verdad. Va INMEDIATAMENTE antes de #133, no después.", "Crear un workspace desechable, pasar el onboarding entero como si fueras un cliente que ve la app por primera vez (sin atajos de super-admin, sin arreglar nada a mano en el camino) y anotar cada punto donde te trabaste. Después borrarlo. Si te trabás vos que lo construiste, Leila se traba seguro."],
  [137, "BYOK de verdad: que cada cliente corra con SUS keys", ["arranque-del-cliente", "multiinquilino-workspace"], 87, 0, 82, 45, "Ojo que son DOS cosas con urgencias distintas: las keys de INTEGRACIONES (Meta, Calendly, Chatwoot) son bloqueantes del viernes —sin su token, Leila ve datos ajenos o no ve nada—; la key de IA NO es bloqueante, se puede diferir unos días comiéndote el costo. Separalas y hacé primero la mitad urgente.", "Terminar el BYOK real. La parte urgente: que cada cliente cargue y corra con SUS credenciales de integración. La parte diferible pero fea: hoy la key de IA del cliente se guarda, se pinta en verde y NO se usa —paga la agencia—; con un cliente era una curiosidad, con tres es una cuenta que crece sola. La infra de credenciales por workspace ya existe; falta cablearla y dejar de mentir en la UI."],
  [139, "Diseño SIMPLE del onboarding", ["arranque-del-cliente", "diseno-simple"], 40, 0, 45, 20, "Parte del barrido transversal de SIMPLE (#159-161), no una tarea suelta: hacerlo ahora es pintar una pared que todavía se está moviendo. Después de que el onboarding modular esté firme.", "Pasada de simplificación sobre el arranque, una vez que #136 dejó de moverse: menos pasos visibles, menos campos, y que en cada pantalla quede clarísimo qué falta y por qué importa."],

  // Versionado — el multiplicador barato
  [140, "Que las tabs se actualicen solas cuando hay un push", ["versionado-actualizaciones"], 86, 0, 72, 20, "Costo bajísimo, ahorro permanente, y desde mañana lo pagan tres clientes en vez de uno. Ya nos comió horas en este mismo desarrollo: bugs reportados sobre builds viejos que hacía rato estaban arreglados. Por eso trepa arriba de features mucho más grandes.", "Que la app se entere sola de que hay una versión nueva desplegada y refresque lo que pueda sin romperte lo que estabas haciendo. La regla: si el que mira la pantalla no sabe qué versión está mirando, cualquier prueba que haga no vale."],
  [141, "Modal 'nueva versión disponible' que no se va hasta que actualizás", ["versionado-actualizaciones"], 84, 0, 68, 15, "El hermano de #140 para lo que NO se puede refrescar en caliente. Que no se pueda cerrar es a propósito: el cartel esquivable se esquiva siempre, y volvés a tener gente probando versiones viejas.", "Cuando el cambio no se puede aplicar solo, un cartel que NO se puede cerrar: 'nueva versión disponible, actualizá'. Sin 'después', sin cruz. Mismo criterio que los avisos del CRM que no se pueden ignorar."],
  [142, "Empezar a enumerar el versionado (v1.0 + qué cambió)", ["versionado-actualizaciones", "infraestructura-propia-e"], 62, 0, 50, 20, "Necesario para poder hablar de 'versiones' con un cliente ('¿qué versión tenés?') pero no frena nada hoy: primero que se actualice sola (#140/#141), después ponerle número.", "Numerar las versiones en serio: qué versión corre cada cliente, qué cambió en cada una y desde cuándo. Es el cimiento para poder actualizar sin cortarle a los que están adentro, que es justo lo que empieza a importar cuando hay tres."],

  // MaKo en WhatsApp — el producto estrella, roto
  [147, "Bug: el pop-up de confirmación aparece DETRÁS del anterior", ["mako-en-whatsapp", "bandejas-de-whatsapp"], 83, 0, 55, 5, "La mejor relación arreglo/esfuerzo de todo el tablero: hoy es literalmente IMPOSIBLE borrar el historial o desconectar el WhatsApp no oficial, y se arregla en un rato. No es una molestia estética: es una función que no existe.", "Al borrar el historial del WhatsApp no oficial (y al desconectar), el pop-up de confirmación se dibuja DETRÁS del pop-up anterior, así que no se puede confirmar y la acción no se puede completar nunca. Es un problema de apilado de capas; hay que revisar los dos pop-ups y de paso los demás casos de pop-up sobre pop-up de la app."],
  [143, "MaKo no guarda contexto en WhatsApp (probarlo contra Claude)", ["mako-en-whatsapp", "tooluse-core-de"], 82, 0, 90, 40, "El diferenciador del producto es hablarle a MaKo por WhatsApp, y justo eso es lo que funciona mal. Un producto donde falla la magia quema la venta más rápido que un producto que no la promete. El más importante del bloque.", "Diagnosticar por qué se olvida de la conversación: mandale tres mensajes encadenados y compará la respuesta contra la misma charla en Claude. Sospechosos, en orden: la ventana de historial que se le pasa al modelo, que el ruteo por turno le esté dando un modelo barato a algo que necesita contexto, y que el hilo del grupo no se esté agrupando como una conversación."],
  [144, "No funciona al crear un grupo de cliente (probado con Mauricio)", ["mako-en-whatsapp"], 80, 0, 78, 30, "Anda en el grupo de pruebas pero se cae justo en el caso real: el grupo de un cliente. Y con tres clientes desde el viernes, el caso real pasa a ser el único que importa. Va pegado a #143 porque probablemente compartan raíz.", "Reproducir el fallo con el grupo de Mauricio y arreglarlo. Mirar primero la lista de grupos habilitados (hoy solo Pruebas y SuperAdmin) y la resolución de a qué cliente pertenece cada grupo: si no resuelve el workspace, el doer no tiene de dónde leer y se queda mudo o contesta genérico."],
  [145, "Crear el grupo solo al escanear el QR del WhatsApp no oficial", ["mako-en-whatsapp", "arranque-del-cliente"], 78, 0, 72, 25, "Es onboarding disfrazado de feature de WhatsApp: hoy el grupo lo armás vos a mano por cliente, y eso no escala más allá de los que podés atender personalmente. Preguntar '¿lo armo con este número?' evita el grupo con el número equivocado, que después no se arregla.", "Cuando el cliente escanea el QR del canal no oficial, ofrecerle crear el grupo de MaKo ahí mismo ('¿querés que arme el grupo con este número?') y armarlo si dice que sí. Un paso menos de config manual y un cliente que sale del arranque con MaKo ya escuchando."],
  [146, "Probar los casos de uso (archivos y preguntas específicas)", ["mako-en-whatsapp"], 70, 0, 62, 18, "Sin esto no sabés qué está roto de verdad: hoy 'funciona mal' es una sensación, no una lista. Va DESPUÉS de #143/#144 porque no tiene sentido catalogar fallas sobre una base que ya sabés que está rota.", "Armar una batería de casos reales y pasarlos todos: mandarle un archivo, un audio, una pregunta puntual sobre un lead, una pregunta sobre los números. Anotar qué contesta bien, qué contesta genérico y qué ignora. El resultado es la lista de qué arreglar, en orden."],
  [148, "Terminar las PLANTILLAS en SuperAdmin", ["mako-en-whatsapp", "comunicacin-con-el"], 68, 0, 65, 45, "Se sigue en otro chat, así que acá queda solo como marcador para que no se pierda del tablero ni se trabaje dos veces.", "Terminar la funcionalidad de plantillas en SuperAdmin (se retomó en una conversación aparte). Hasta que eso cierre, esta tarjeta es solo el marcador en el tablero."],

  // Retro — el loop de accountability
  [154, "Conectar Retro ⇄ Plan ⇄ WhatsApp (el loop de accountability)", ["retro-real-rendicin", "board-plan-perro", "mako-en-whatsapp"], 64, 0, 78, 45, "OJO: esto figuraba en tus DOS listas (Retro 6 y Plan 1). Es un solo build, no dos, y es la pieza que convierte Retro y Plan de dos pantallas separadas en un sistema. Lo más alto del bloque porque #155 y #158 dependen de esto.", "El circuito completo: el Plan sabe qué hiciste y cuándo, la Retro lo lee (en vez de preguntar si tocaste 'Aceptar'), y MaKo te lo reclama por WhatsApp donde sí lo vas a ver. Hoy son tres piezas que no se hablan y por eso la rendición de cuentas es de mentira. Hacerlo una sola vez, con las tres puntas juntas."],
  [155, "Si no completaste la Retro anterior, no ejecutar la nueva: reclamar y debatir", ["retro-real-rendicin", "board-plan-perro"], 62, 0, 75, 38, "Es la idea más filosa de todo el lote: convierte la Retro de informe caro que pedís cuando querés en un coach que te persigue. Depende de #154 (sin saber qué hiciste de verdad, no puede reclamar nada). El 'a la fuerza, debatiendo' es clave: si se puede saltear en silencio, se saltea siempre.", "Si quedaron tareas y experimentos sin completar de la Retro anterior, la nueva NO se ejecuta: primero te empuja a terminar lo de antes. Se puede forzar, pero solo debatiendo con MaKo por qué ignoraste lo anterior — y esa respuesta queda registrada. Cuidado con la trampa: que la fricción sea proporcional, o vas a terminar odiando tu propia Retro."],
  [153, "Que la Retro se ejecute SOLA", ["retro-real-rendicin", "pulso-diario-vista"], 60, 0, 70, 35, "Es el latido que le falta a todo el producto: una Retro que solo corre cuando te acordás de pedirla no es un coach, es un botón. Pero va después de #154 porque una Retro automática sobre datos que no sabe si hiciste algo es ruido automático.", "Que la Retro corra sola con su cadencia, sin que la pidas, y te avise cuando hay algo para mirar. Mismo patrón que el resto: barato y periódico, razona liviano y te busca a vos en vez de esperarte."],
  [152, "La Retro no tiene fecha de creación ni de ejecución", ["retro-real-rendicin"], 58, 0, 50, 10, "Barato y bloqueante de lo de arriba: sin fecha no hay 'la Retro anterior', y sin 'la anterior' no existe ni #155 (el gate) ni #153 (la cadencia). Empezá por acá el bloque de Retro, es media hora.", "Que cada Retro guarde y muestre cuándo se creó y cuándo se ejecutó. Suena a detalle de UI y en realidad es el cimiento del bloque entero: todo lo que viene después necesita poder preguntar '¿cuándo fue la última?' y '¿cuánto pasó desde entonces?'."],
  [149, "Falta el perro en la Retro", ["retro-real-rendicin", "board-plan-perro"], 55, 0, 60, 30, "El Perro Guardián ya prioriza y debate en /todo; la Retro es justo donde más falta hace porque es donde se decide qué hacer. Es reusar un cerebro que ya existe, no construir uno nuevo.", "Traer el Perro Guardián a la Retro: que priorice lo que propone, lo debata con vos y cuide que no se convierta en una lista de 20 cosas que no vas a hacer. El cerebro ya está construido y andando en el Plan de ejecución; acá es enchufarlo."],
  [151, "Revisar el algoritmo para que la Retro cree más tareas", ["retro-real-rendicin"], 52, 0, 55, 22, "Una Retro que mira todo el negocio y saca dos tareas está dejando plata en la mesa. Pero primero el loop (#154): una Retro que produce MÁS tareas y no verifica ninguna es más ruido, no más valor.", "Ajustar el algoritmo para que detecte más oportunidades y proponga más tareas y experimentos. Ojo con el equilibrio: más tareas sin el gate de #155 es una lista más larga de cosas ignoradas. Van juntas."],
  [150, "Diseño SIMPLE de la Retro", ["retro-real-rendicin", "diseno-simple"], 38, 0, 42, 20, "Parte del barrido de SIMPLE (#159-161). Va al final del bloque de Retro por la misma razón de siempre: no se simplifica una pantalla cuyo contenido todavía se está moviendo.", "Pasada de simplificación sobre la Retro una vez que dejó de cambiar: menos de todo, y arriba lo único que importa (qué me está diciendo y qué hago al respecto)."],

  // Plan — el otro extremo del loop
  [157, "Bugs en la vista del cliente del Plan", ["board-plan-perro"], 72, 0, 52, 18, "Ojo con esta: si /plan entra en la capa que se vende YA (#132), esto deja de ser un bug menor y pasa a ser bloqueante del viernes, porque es literalmente una de las pantallas que van a abrir Leila y Leandro. Definí #132 primero y después mirá si esto sube o baja.", "Cazar y arreglar los bugs de la vista del cliente del tablero (la que NO es la de agencia). El componente es el mismo para los dos, así que lo más probable es que sea permisos o datos que el cliente no tiene y la vista asume que sí."],
  [158, "INCLUIR EL FACTOR TIEMPO en el Plan + seguimiento", ["board-plan-perro", "retro-real-rendicin"], 63, 0, 72, 35, "Es la otra mitad de #155: sin tiempo, 'no completaste lo anterior' no se puede ni calcular. Un tablero sin fechas no hace seguimiento, hace inventario. Va junto con #154, no después.", "Meterle tiempo al tablero: cuándo se creó cada tarea, para cuándo es, cuánto lleva parada, y que MaKo haga seguimiento sobre eso en vez de mirar una foto sin fecha. Es lo que le da a la Retro con qué reclamarte."],
  [156, "Terminar las tareas predefinidas del Plan", ["board-plan-perro"], 50, 0, 48, 20, "Lo que hace que el tablero del cliente no arranque vacío —y un tablero vacío es un tablero que no se usa—. Aplica el principio de siempre: mejor una plantilla que una pantalla en blanco pidiendo config.", "Terminar el juego de tareas predefinidas que se siembran al arrancar, para que un cliente nuevo abra el Plan y ya tenga sus primeras secuencias ahí, en vez de una columna vacía y un botón de '+'."],

  // Diseño SIMPLE — el barrido final
  [159, "Modo Avanzado (y que SIMPLE sea el default)", ["diseno-simple", "arranque-del-cliente"], 42, 0, 52, 30, "La pieza que hace posible simplificar sin perder nada: sin un lugar donde guardar lo denso, cada simplificación es una pelea. Es la primera del bloque, pero el bloque entero va al final porque el contenido todavía se mueve.", "Un toggle Avanzado a nivel app: SIMPLE por default (lo mínimo para decidir y actuar) y todo el detalle denso a un clic para el que lo quiera. Se apoya en el criterio que ya usa el Plan (3 tareas + experimentos por default, kanban completo detrás del toggle) y lo lleva al resto."],
  [160, "Las tabs SIMPLE que faltan (Script y Closing Analyst)", ["diseno-simple", "ads-analyst-analista", "closing-analyst-analista"], 34, 0, 40, 25, "Las dos que quedaron afuera del barrido. Son analistas densos por naturaleza, así que son justo las que más ganan con el modo Avanzado (#159) — y por eso van después de él, no antes.", "Pasar Ads Analyst y Closing Analyst por el mismo criterio que el resto: arriba el veredicto y la secuencia de mensajes, y toda la tabla densa detrás del toggle Avanzado."],
  [161, "Revisar TODAS las tabs: ¿son SIMPLES de verdad?", ["diseno-simple", "reskin-de-la"], 32, 0, 42, 35, "La pasada honesta al final: la pregunta no es '¿me resulta simple?' sino '¿le resulta simple a alguien que la ve por primera vez?'. Vos ya no podés ver tus propias pantallas con ojos nuevos, así que conviene hacerla con un cliente real mirando.", "Auditoría tab por tab con una sola pregunta: ¿esto es simple, o solo estoy acostumbrado? Lo que no pase el filtro, o se simplifica o se manda a Avanzado. Cerrar el barrido de una sola vez, no de a goteo."],

  // ── Auditoría del 16/7: rutas, aislamiento y honestidad del dato ─────────────
  // Salieron de investigar el pedido "¿qué otras rutas se nos están escapando?".
  // El patrón de fondo: el repo trata la PÁGINA como unidad de autorización,
  // cuando las unidades reales son el BUNDLE, la API y la FILA.
  [162, "Fuga cross-tenant: un cliente puede secuestrarle los webhooks a otro", ["cerrar-la-auditora", "multiinquilino-workspace"], 99, 0, 97, 25, "Es exactamente el 'jamás nada se debe pasar de un workspace a otro', está vivo HOY, y el viernes pasás de 1 cliente a 3 — que es justo el día en que deja de ser teórico. No necesita credenciales robadas: los identificadores son públicos. Le gana a todo lo demás del tablero.", "upsertRouting reasigna un identificador a otro workspace con un console.warn y sigue de largo: no verifica que quien lo reclama sea el dueño. Un admin de cliente manda su meta_page_id (o el event type de Calendly, o el mail de Fathom — ninguno es secreto) y desde ahí los webhooks le entregan a SU CRM los leads, chats, transcripts y reuniones de la víctima. Y borrando la credencial deja al otro sin ingesta. El fix: que reclamar un identificador ya mapeado falle cerrado (409 + aviso), nunca pise; verificar posesión con el token del propio workspace; índice único (servicio, identificador) con 'primer reclamante gana'. El patrón defensivo ya existe en landing-token.ts."],
  [163, "El roadmap de la agencia viaja al browser de cada cliente", ["cerrar-la-auditora", "board-plan-perro"], 88, 0, 80, 15, "No hace falta ni teclear una URL rara: /plan está en el nav de todos y el chunk ni siquiera está detrás del login. Y no es solo el roadmap — el detalle del proyecto de auditoría describe por escrito los agujeros abiertos, o sea que es un mapa de ataque. Barato de arreglar y de los más vergonzosos si alguien lo mira.", "PlanBoard.tsx es 'use client' y se importa estático en page.tsx, así que Next manda su chunk en el JS de /plan para TODOS aunque el server renderice el TodoBoard del cliente. Se lee en DevTools → Sources: proyectos, scoring interno, fechas y razonamiento estratégico crudo. next/dynamic NO alcanza (el chunk igual se emite): el código puede viajar, los DATOS no. Cargar el seed en el server bajo getSesionAdmin() y pasarlo por props, o mover el board de agencia a su propio segmento y que /plan importe solo TodoBoard."],
  [164, "La Retro miente cuando el cliente solo conectó Meta", ["retro-real-rendicin", "arranque-del-cliente"], 90, 0, 88, 30, "Es el WOW del onboarding y hoy es contraproducente: le dice a un cliente nuevo que su negocio factura $0 el día 1. No queda flojo, queda incompetente — y encima es culpa nuestra, no del dato. Bloquea el arranque de Leila y Leandro, por eso va arriba de casi todo.", "Con solo Meta, Conversión y Revenue no se saltean: sus queries devuelven ceros estructurales y entran igual al prompt. Resultado garantizado: 'ROAS cash 0.00x, gastaste $X y facturaste $0' y 'CUELLO: Formulario → Agenda 0.0%' (gana siempre, severidad máxima). Y la anomalía de nutrición es autoinfligida: el paso anterior del mismo wizard seedea 5 secuencias activas con 0 inscriptos. Fix: derivar 'areas' de las integraciones conectadas y pasárselo TAMBIÉN a recolectarDatos (si no, el cerebro sigue viendo los ceros) + filtrar los charts + que RetroReport no abra en Closing + que textoRevenue/textoConversion devuelvan null cuando no hay fuente (hoy devuelven texto cuando la query 'no explota') + sourceMap a getFunnelEtapas + reglas de cobertura para CRM/agendas/pagos."],
  [165, "El semáforo certifica salud de un negocio del que no sabe nada", ["pulso-diario-vista", "arranque-del-cliente"], 82, 0, 70, 10, "Media hora de trabajo y evita el peor primer contacto posible: luz verde y 'buen momento para empujar volumen' a alguien que no conectó nada. No parece roto, parece mentiroso — y eso se lleva puesta la credibilidad del resto. Casi gratis, alto retorno.", "Con cero fuentes comerciales las alertas quedan vacías y el veredicto cae al else final: verde, 'El negocio está sano · Sin focos activos', y la card de pendientes remata con 'datos al día — el tablero es confiable'. Falta un cuarto estado gris/amarillo 'sin datos suficientes para opinar — conectá X'. La pieza ya existe y está desmontada: lib/sources.ts distingue 'la fuente no está' de 'la fuente dice cero' (por eso /marketing se ve honesta) y el componente SourceStrip no lo monta ninguna página."],
  [166, "Las tabs que dependen de una conexión no deben mostrarse vacías", ["arranque-del-cliente", "diseno-simple"], 80, 0, 76, 35, "Es el mecanismo que hace que el onboarding progresivo exista, y de paso el mismo que permite vender módulos sueltos: cada tab se auto-configura al entrar. Una sola pieza que sirve para las dos cosas.", "Comercial, WhatsApp, Closing y Ads Analyst hoy se muestran vacías o en cero cuando falta su integración — Comercial renderiza seis secciones en $0 y se lee como roto; WhatsApp dice 'Sin conversaciones' cuando en realidad no está conectado. En vez de eso: la misma pantalla dividida del onboarding pidiendo lo que falta. Generalizar el patrón que ya está bien hecho en DominioSetup de /email en un componente reusable: cada tab declara qué necesita (integración/setting/flag), muestra el panel sobre el empty state (no modal bloqueante) y deriva el progreso del estado REAL de conexión, no de un checkbox."],
  [167, "Un closer de la agencia puede borrar campañas de Meta", ["cerrar-la-auditora", "rplica-de-meta"], 78, 0, 62, 5, "Un '&&' de una línea. No es cross-tenant, pero es plata real: borrar y despausar campañas con presupuesto. El repo ya sabe cómo se arregla porque lo tapó en un solo lugar.", "esWorkspaceDueno() es solo 'el workspace actual es el dueño' y no mira el rol, así que un closer o setter de ws1 pasa el guard y llega a las 10 rutas de Ads Manager y a meta-write: publicar, pausar, renombrar, cambiar presupuesto y borrar. El patrón correcto ya está escrito en /api/anthropic-usage, que además exige rol 'admin': llevar ese mismo chequeo adentro de guardAdsDueno."],
  [168, "Un closer puede exportarse la metodología curada de la agencia", ["cerrar-la-auditora"], 76, 0, 65, 12, "Es el hallazgo real detrás de '/conocimiento': arreglar el guard de la página es teatro, porque la fuga está en la API y la alcanza hasta un rol al que la página le rebota. Y no es que la IA la use (eso es a propósito): es que un humano se la copia en texto plano.", "/api/mako/knowledge no tiene ningún chequeo de rol, solo el login. Cualquier logueado —incluido un closer/setter, a quien la página manda de vuelta a /leads— hace GET del catálogo curado completo y POST seed_curso para importarse las entradas enteras a su workspace y leerlas verbatim. Ojo con el matiz: el RAG ya sirve a propósito las filas del dueño a todos los clientes (wsParaRag), así que la IA usando el método es diseño; el problema es la exportación en texto. Fix: gatear seed_curso con getSesionAdmin() y filtrar los curados del GET para no-admins. Y aparte, si querés la página solo-agencia, cambiar requireRolWs([]) por getSesionAdmin() copiando /contexto."],
  [169, "requireRolWs deja pasar a un usuario suspendido", ["cerrar-la-auditora", "cuentas-roles-y"], 72, 0, 60, 8, "Es un bypass de revocación: suspendés a alguien y sigue entrando hasta que le vence la cookie (30 días). Una línea, y cubre las ~30 páginas que usan el guard. Lo tapa el proxy hoy, pero una red que depende enteramente de otra red no es una red.", "El chequeo es 'if (rol != null && rol !== admin && !permitidos.includes(rol)) redirect', así que cuando getRolWsEfectivo() devuelve null NO redirige y la página renderiza. Cadena real: el proxy valida el token con cripto pura sin tocar la base, así que un usuario suspendido o eliminado con cookie firmada pasa; getUsuarioActual() da null; el rol da null; el guard no corta. Atenuante: getWorkspaceActual sí es fail-closed, así que ve el cascarón vacío. Fix: 'if (rol == null) redirect' antes del check."],
  [170, "META_PAGE_ID hardcodeado: bomba de tiempo antes de abrir Ads Manager", ["cerrar-la-auditora", "rplica-de-meta"], 66, 0, 58, 30, "Hoy NO explota (los 10 call-sites están gateados owner-only, lo verifiqué uno por uno), pero es exactamente la mina que se pisa el día que Ads Manager se abra a clientes. Cerrarlo ANTES de abrir, no después. Más abajo que las fugas vivas justamente porque todavía es latente.", "lib/config.ts tiene la página de Facebook del dueño como literal y meta-ads-create.ts la usa sin scopear por workspace en object_story_spec, promoted_object, leadgen_forms y reglas de públicos; getEnv() lee process.env crudo salteándose credWs/BYOK, a contramano de todo lo que ya se migró. Igual con META_PIXEL_ID. El andamiaje por-workspace YA existe (META_PAGE_ID está en el catálogo BYOK): falta recablear meta-ads-create a credWs por workspace, fail-closed si falta, y borrar la constante."],
  [171, "meta_page_id y META_PAGE_ID: dos fuentes de verdad que no se hablan", ["cimientos-de-datos", "arranque-del-cliente"], 64, 0, 55, 15, "Trampa de soporte silenciosa justo en el arranque: el cliente hace todo bien por donde el copy lo empuja y la ingesta no arranca, sin ningún error visible. Con tres clientes desde el viernes, esto se convierte en tres consultas de '¿por qué no veo leads?'.", "Hay dos cosas homónimas: la setting meta_page_id (minúscula, la escribe el wizard y es la que lee pollMetaLeads para ingestar) y la credencial META_PAGE_ID (mayúscula, cifrada, la ofrece /integraciones diciendo 'se usa para rutear los leads entrantes'). Las dos espejan a webhook_routing, pero el cron solo lee la setting: quien la cargue por /integraciones tiene el ruteo andando y la ingesta muerta con 'meta_page_id no configurado'. Unificar en la credencial y que la setting sea alias de lectura. Relacionado: META_PAGE_ACCESS_TOKEN está como '(opcional)' en la card de Meta y sin él el job de leads queda 'skipped' → 0 leads → se apagan en cascada CRM, Comercial y el hero de General. Es la causa raíz del 'desierto' del cliente nuevo."],
  [172, "Comprar el chip y darle voz propia a MaKo", ["mako-en-whatsapp", "infraestructura-propia-e"], 60, 0, 68, 10, "Prerequisito, no mejora: hoy MaKo le habla a los clientes desde el número personal de Martín. Con tres clientes desde el viernes, todos los grupos salen de tu celular — si te banean, se cae el WOW de todos a la vez. Barato en esfuerzo, alto en riesgo evitado; el perro decide contra qué compite.", "La instancia de voz por default es mako_ws1, o sea tu línea. Ya existe el canal dedicado (mako_superadmin) y la función para usarlo como voz: falta el chip y escanear el QR una vez. Mientras no esté, cada grupo de cliente que se crea y cada mensaje que MaKo manda sale de tu número, con el riesgo de ban de WhatsApp que eso implica y sin separación entre tu vida y el producto."],
  [173, "Tabs precarias: MaKo Doer y Ads Writer", ["diseno-simple", "tooluse-core-de"], 45, 0, 50, 35, "Son dos tabs que un cliente PUEDE abrir hoy y que no están a la altura del resto: no rompen nada, pero desentonan. No urgente frente a las fugas y el arranque, pero conviene antes de mostrárselas a alguien que paga.", "/mako-doer y /ads-writer están muy por detrás del resto de la app. El doer web tiene 6 tools de lectura pero contesta 'no encontré leads' a la mitad de las preguntas en un cliente nuevo (honesto pero inútil), vive aislado en su tab y no está embebido en ninguna pantalla. Ads Writer funciona para cualquier workspace (es de las pocas que anda sin config) pero es un generador pelado. Definir para cada una: o se llevan al estándar del producto, o se esconden hasta que estén."],
  [174, "Calendly: el cliente conecta, no entra nada y no hay ningún error", ["cerrar-la-auditora", "cimientos-de-datos", "arranque-del-cliente"], 84, 0, 80, 25, "Es el mismo patrón que la key de IA — se guarda, se pinta verde, no se usa — pero este además rompe el producto en silencio: sin agendas no hay cohortes, ni funnel, ni SCL, ni revenue. Un cliente que sigue el tutorial al pie de la letra termina con Comercial vacío y sin una sola pista de por qué. Alto impacto, esfuerzo medio-bajo: es cablear lo que ya existe.", "Dos agujeros en el mismo camino. (1) La signing key que el cliente pega se guarda cifrada y el catálogo le promete que 'con él MaKo verifica la firma de cada webhook' — pero el webhook lee SOLO process.env.CALENDLY_WEBHOOK_SIGNING_KEY: su webhook propio devolvería 401 para siempre. (2) Los event types de R1/R2 están marcados opcionales pero el ruteo los exige: sin ellos wsPorIdentificador devuelve null y el route corta fail-closed devolviendo 200 OK y descartando el evento, o sea 'Calendly conectado' + cero agendas + ningún error. El fix: leer credWs con fallback al env, y resolver el workspace ANTES de verificar la firma para saber contra qué llave verificar; y des-opcionalizar los event types o avisar. Mientras tanto el catálogo de activación de tabs lo dice en criollo en vez de prometer 'entra solo'."],

  // ── 175-184 · trabajo del 16-17/7 que no tenía tarjeta (cardado al reconciliar) ──
  // Score bajo a propósito: casi todo ya está HECHO (progreso alto), así que como
  // pendiente pesa poco. La excepción es #177 (la persistencia del board), que NO
  // está hecha y es el cuello de todo el loop de accountability.
  [175, "El historial del board dice quién y qué (MaKo vs Claude Code) + buscar por #id", ["board-plan-perro"], 24, 100, 30, 20, "Cerrado. El board firmaba 'MaKo' todo lo que en realidad escribió un agente de dev, y el renderer tiraba el texto del alta: dos mentiras chicas que erosionaban la única fuente de auditoría del backlog.", "Se separó el actor 'code' (Claude Code, todo el SEED) del 'ia' (MaKo, la IA del producto), con partirCreacion/autorDe/frasePorAlta en los 3 renderers, histDeCarga firmando cada tanda con su fecha real, y la migración del localStorage ya escrito. Además: buscar por #id en kanban y Proyectos (antes passes() nunca miraba t.num), y una pasada de minimalismo (fuera la descripción de Prioridades, el 'Por qué es el norte', el chip de origen del kanban que estaba en 173/173 tarjetas, la descripción de Proyectos)."],
  [176, "Fathom: el selector de reuniones trae el histórico completo", ["board-plan-perro"], 20, 100, 25, 15, "Cerrado. Un detalle que hacía parecer que Fathom 'no tenía' las reuniones viejas.", "listReunionesRecientes() pedía UNA página (30) y el selector mostraba solo eso. Ahora usa fetchAllMeetings(), el paginador por cursor que ya corría en prod para el Closing Analyst; sigue trayendo metadata liviana (el transcript se baja recién al elegir una)."],
  [177, "El board de Martín no se persiste en el servidor (vive en localStorage)", ["board-plan-perro", "retro-real-rendicin"], 70, 0, 78, 55, "El cuello de TODO el loop de accountability. La Retro puede escribirle tareas al board del CLIENTE (experimento_tareas) y verificar si las hizo — pero el board de Martín vive en el localStorage de su navegador con los 6 métodos del Repo en no-op, así que ningún código de servidor sabe si él completó algo. Sin esto, el gate de la Retro no puede existir para el dueño.", "Hoy /plan/agencia renderiza PlanBoard, que persiste TODO en localStorage (K9='mako_plan_v9') y cuyo Repo es literal no-op (createTask/saveTask/deleteTask vacíos). El TodoBoard del cliente sí persiste en experimento_tareas vía lib/todo.ts. Migrar el board del dueño a la base es el prerequisito no escrito de #154 (loop Retro⇄Plan) y del factor tiempo (#158): recién cuando el servidor pueda LEER el plan de Martín, la Retro puede reclamarle lo que no hizo."],
  [178, "El aside del onboarding muestra datos reales del cliente al conectar (FACTS)", ["arranque-del-cliente"], 30, 100, 45, 25, "Cerrado. 'La promesa se reemplaza por la prueba': apenas conectás una integración, el carrusel de marketing del panel negro se cae y aparece tu propio dato.", "lib/metodo-verificar.ts suma el tipo Fact {k,v,c} a ResultadoVerificacion (aditivo) en 6 servicios: meta (nombre de la cuenta + estado), whatsapp (bandeja + número), fathom (última llamada + 'hace 2 días'), calendly (conectado como + agenda), email (dominio verificado o sandbox), panda (último video). El dato ya venía en la respuesta y se descartaba. ServicioConfigForm los emite con onFacts y PanelActivacion los pinta. Complementa #166 (que cubría la pantalla partida, pero no los facts)."],
  [179, "Borrar /koncke: un copiloto con datos de OTRO inquilino y sin guard", ["cerrar-la-auditora"], 26, 100, 55, 10, "Cerrado. Ruta huérfana en prod, sin ningún guard: cualquier usuario logueado de cualquier workspace la abría tecleando la URL y veía chips verdes afirmando 'Koncke usa tu data en vivo' sobre leads y campañas de otro cliente.", "/koncke era un port del prototipo design-reference que quedó vivo: sin LLM, matcheaba keywords contra respuestas hardcodeadas que citaban 'Salvador Loza' y '286 leads'. 291 líneas borradas; su sucesor real (/mako y /mako-doer) ya está en prod. Prima de #173 ('Tabs precarias'), que solo nombraba /mako-doer y /ads-writer."],
  [180, "Escalada a super-admin: la llave de firma de sesión viajaba al browser", ["cerrar-la-auditora"], 40, 100, 92, 20, "Cerrado — era la vulnerabilidad más grave del lote. Cualquiera con la cookie de la contraseña maestra se forjaba un token de super-admin de la agencia.", "El token es v1.<payload>.<HMAC> con el rol adentro, y secret() era AUTH_SECRET || AUTH_COOKIE_VALUE || DASHBOARD_PASSWORD. Con AUTH_SECRET inexistente en Vercel, la llave de firma ERA AUTH_COOKIE_VALUE, que se compara tal cual contra la cookie del browser: estaba en el navegador de todos, y tieneFila() saltea el re-chequeo contra la base cuando sub==='password'. Se contuvo seteando un AUTH_SECRET de 256 bits (el deslogueo masivo ES el parche). Suma INFRA_ENV protegiendo AUTH_SECRET/DASHBOARD_PASSWORD/GOOGLE_CLIENT_ID/SECRET y el borrado de filas zombie de credenciales que se pisaban sobre el entorno en cada boot."],
  [181, "Cifrado de credenciales v2 (HKDF por workspace + AAD)", ["cerrar-la-auditora"], 32, 100, 70, 40, "Cerrado (código + migración + tests). La llave que cifraba las 30 credenciales era AUTH_COOKIE_VALUE, que viaja al browser: con un dump de la base, quien tuviera esa cookie las leía.", "lib/cripto-credenciales.ts (fuera de server-only, testeable) con dos formatos conviviendo: gcm1 (sha256 del secreto, sin sal) y gcm2 (HKDF-SHA256 por workspace+clave, con AAD), lector dual + escritor detrás de flag. Suma mig 0091 (auditoría durable de quién tocó qué llave, con los rechazados y nunca el valor), runbook, scripts/recifrar-credenciales.mjs y 18 tests. La revisión adversarial atajó dos bugs reales: el backfill se comía en silencio el refresh_token de Google Calendar (vive en app_settings, no en credenciales) y googleCalendarConectado() no descifraba."],
  [182, "Fuga del EVOLUTION_WEBHOOK_SECRET (secreto de plataforma) al browser del cliente", ["cerrar-la-auditora"], 34, 100, 80, 15, "Cerrado. Un secreto compartido por TODOS los clientes viajaba en claro: con él se forjan webhooks de WhatsApp de cualquier workspace (mensajes inventados en el CRM ajeno).", "webhookUrl() metía EVOLUTION_WEBHOOK_SECRET en la query y estadoWebhook() devolvía esa URL entera; el guard de /api/whatsapp/evolution es 'admin del workspace' = cualquier cliente. Un admin de cliente pedía 'webhook-estado' y se llevaba el secreto. La UI solo leía `estado`: el secreto viajaba sin que nadie lo mirara. Se recortan los 8 returns con el sinQuery que ya existía. Del mismo barrido: el logout no limpiaba la cookie de impersonación (mako_ws, 12h), así que un admin que impersonaba y cerraba sesión volvía metido en el workspace del cliente."],
  [183, "Gate de sesión en rutas que queman IA de la agencia a cuenta de cualquiera", ["cerrar-la-auditora"], 24, 100, 45, 10, "Cerrado. Rutas de IA cara sin chequeo propio de sesión.", "/api/mako-guardian entraba de req.json() directo a razonar con effort 'high' y maxTokens 8000 sin gate propio (no abierta a internet —proxy.ts la cubre— pero era la única del par sin el chequeo; su hermana /api/plan-fathom sí lo tenía). Se le puso getUsuarioActual(). En el mismo espíritu se cerraron /api/mako/knowledge/transcribe (Whisper) y /api/mako/onboarding/extract."],
  [184, "Incidente: nadie podía entrar con Google (scope sensible de Calendar en el login)", ["cuentas-roles-y"], 28, 100, 85, 15, "Cerrado — era un incidente de producción en vivo. El login quedó restringido a testers aprobados y todo el resto recibía 403 access_denied.", "El login pedía GCAL_SCOPE (calendar.readonly), un scope SENSIBLE de Google: una app que lo pide y no está verificada solo la usan los testers. Se combinó con el parche de AUTH_SECRET (que deslogueó a todos y destapó la pared). El fix saca el scope de la puerta de calle (login → 'openid email profile') y quita access_type=offline (sin el scope no hay nada que refrescar, y pedirlo devolvería un refresh_token sin permiso de agenda que el callback guardaría como si fuera el de Calendar). La agenda se conecta aparte, en /api/integraciones/google-calendar."],
];

