function reconcileChecklists(tasks: BoardTask[]): BoardTask[] {
  try {
    if (localStorage.getItem('mako_plan_reconcile') === RECONCILE_VERSION) return tasks;
    localStorage.setItem('mako_plan_reconcile', RECONCILE_VERSION);
    return tasks.map((t) => {
      const viejos = RECONCILE_DONE[t.num] ?? [];
      const nuevos = RECONCILE_DONE_17J[t.num] ?? [];
      const cl = buildCL(t.num);
      if ((!viejos.length && !nuevos.length) || !cl.length) return t;
      const mk = (text: string, i: number, ts: number, sfx: string): Hist =>
        ({ id: 'rec' + sfx + t.num + '_' + i, ts: ts - i * 1000, actor: 'code', text: `Completó "${text}"`, kind: 'task' });
      const entries: Hist[] = [
        ...nuevos.map((text, i) => mk(text, i, RECONCILE_TS_17J, 'b')),
        ...viejos.map((text, i) => mk(text, i, RECONCILE_TS, '')),
      ];
      return { ...t, checklist: cl, progress: clProgress(cl, t.progress), historial: [...entries, ...t.historial].slice(0, HIST_CAP) };
    });
  } catch { return tasks; }
}

// Bandeja de WhatsApp → tarjetas del board (punto 8). MaKo dejó estas tareas para el
// dueño; nacen con origen 'ia' (MaKo las creó de verdad, distinto del SEED='code') y
// con el refId como id, para que el deep-link /plan/agencia?tarea=<refId> las abra.
type TareaInboxRaw = { refId?: string; titulo?: string; prioridad?: string; proyecto?: string; deadline?: string; detalle?: string; ts?: number; fuente?: { tipo?: string; etiqueta?: string; url?: string } };
const FUENTE_WA: Fuente = { tipo: 'whatsapp' }; // fuente de las tareas/proyectos que entran por WhatsApp
const INBOX_SEEN = 'mako_plan_inbox_seen'; // refIds ya mergeados por ESTE browser (dedup por device)
function loadSeen(): Set<string> { try { const v = localStorage.getItem(INBOX_SEEN); return new Set(v ? (JSON.parse(v) as string[]) : []); } catch { return new Set(); } }
function saveSeen(s: Set<string>) { try { localStorage.setItem(INBOX_SEEN, JSON.stringify([...s].slice(-1000))); } catch { /* no-op */ } }
const OPS_SEEN = 'mako_plan_ops_seen'; // opIds ya aplicados por ESTE browser
function loadSeenOps(): Set<string> { try { const v = localStorage.getItem(OPS_SEEN); return new Set(v ? (JSON.parse(v) as string[]) : []); } catch { return new Set(); } }
function saveSeenOps(s: Set<string>) { try { localStorage.setItem(OPS_SEEN, JSON.stringify([...s].slice(-2000))); } catch { /* no-op */ } }

// Una operación que Claude Code / MaKo dejó para aplicar sobre una tarea EXISTENTE.
type PlanOpRaw = { opId?: string; op?: string; num?: number; campos?: { titulo?: string; detalle?: string; deadline?: string; prioridad?: string; proyecto?: string; score?: number }; etiqueta?: string; ts?: number };

// Aplica las operaciones (completar/reabrir/editar/proyecto/prioridad/borrar) matcheando
// por #num. Deja rastro en el historial (actor 'code'). Pura, como construirInbox.
function aplicarOps(items: PlanOpRaw[], tasksIn: BoardTask[], labelsIn: Label[]): { tasks: BoardTask[]; labels: Label[] } {
  let tasks = tasksIn;
  let labels = labelsIn;
  const byName = new Map(labels.map((l) => [l.name.trim().toLowerCase(), l]));
  const PRI = ['alta', 'media', 'baja', 'futuro'] as const;
  for (const op of items) {
    const num = Number(op.num);
    const idx = tasks.findIndex((t) => t.num === num);
    if (idx < 0) continue; // #num inexistente (viejo/borrado) → se ignora
    const etq = op.etiqueta ? ` · ${op.etiqueta}` : '';
    const mkH = (text: string): Hist => ({ id: 'op' + uid(), ts: Number(op.ts) || Date.now(), actor: 'code', text: `${text} — Claude Code${etq}` });
    if (op.op === 'borrar') { tasks = tasks.filter((_, i) => i !== idx); continue; }
    const t = tasks[idx];
    let nt: BoardTask = { ...t };
    const c = op.campos || {};
    if (op.op === 'completar') { nt = { ...nt, progress: 100, checklist: nt.checklist.map((x) => ({ ...x, done: true })), historial: [mkH('Completó la tarea'), ...nt.historial].slice(0, HIST_CAP) }; }
    else if (op.op === 'reabrir') { nt = { ...nt, progress: 0, historial: [mkH('Reabrió la tarea'), ...nt.historial].slice(0, HIST_CAP) }; }
    else if (op.op === 'prioridad') { const sc = clampScore(Number(c.score)); nt = { ...nt, score: sc, priority: prioFromScore(sc), historial: [mkH(`Cambió la prioridad → ${sc}`), ...nt.historial].slice(0, HIST_CAP) }; }
    else if (op.op === 'editar') {
      if (c.titulo) nt.title = String(c.titulo).slice(0, 200);
      if (typeof c.detalle === 'string') nt.detalle = c.detalle;
      if (typeof c.deadline === 'string') nt.deadline = c.deadline;
      if (c.prioridad && (PRI as readonly string[]).includes(c.prioridad)) { const p = c.prioridad as Prio; nt.priority = p; nt.score = scoreFromPrio[p]; }
      nt.historial = [mkH('Editó la tarea'), ...nt.historial].slice(0, HIST_CAP);
    } else if (op.op === 'proyecto') {
      const nombre = String(c.proyecto || '').trim();
      if (nombre) {
        let lab = byName.get(nombre.toLowerCase());
        if (!lab) { const lid = 'op' + uid(); lab = { id: lid, pid: `P${labels.length + 1}`, emoji: '📁', name: nombre.slice(0, 60), color: '#2F6FED', score: 50, detalle: '', historial: [{ id: 'opl' + lid, ts: Number(op.ts) || Date.now(), actor: 'code', text: `Creó el proyecto — Claude Code${etq}` }] }; labels = [...labels, lab]; byName.set(nombre.toLowerCase(), lab); }
        nt = { ...nt, labels: [lab.id], historial: [mkH(`Asignó a «${nombre}»`), ...nt.historial].slice(0, HIST_CAP) };
      }
    } else continue;
    tasks = tasks.map((x, i) => (i === idx ? nt : x));
  }
  return { tasks, labels };
}

// Construye las tarjetas de la bandeja Y crea el PROYECTO que falte (igual que la rama
// cliente): si el nombre no matchea un label, se crea uno nuevo, así el proyecto no se
// pierde en silencio. Los num van en un rango alto (≥9000) para no chocar con el SEED
// (que crece de a poco desde #1 y con mergeExtras descartaría un num pisado).
function construirInbox(items: TareaInboxRaw[], existentes: BoardTask[], labels: Label[]): { tasks: BoardTask[]; labels: Label[] } {
  let maxN = Math.max(8999, existentes.reduce((m, t) => Math.max(m, t.num), 0));
  const byName = new Map(labels.map((l) => [l.name.trim().toLowerCase(), l]));
  const nuevos: Label[] = [];
  const tasks = items
    .filter((it) => (it.titulo || '').trim())
    .map((it) => {
      const p: Prio = (['alta', 'media', 'baja', 'futuro'] as const).includes(it.prioridad as Prio) ? (it.prioridad as Prio) : 'media';
      // La fuente sale de la bandeja (Claude Code trae la suya con el link del chat); si
      // no viene, es WhatsApp (compat). El actor y el texto del historial la respetan.
      const esCode = it.fuente?.tipo === 'claude-code';
      const fuente: Fuente = it.fuente?.tipo ? { tipo: it.fuente.tipo as Fuente['tipo'], etiqueta: it.fuente.etiqueta, url: it.fuente.url } : FUENTE_WA;
      const actor: Actor = esCode ? 'code' : 'ia';
      const desde = esCode ? (it.fuente?.etiqueta ? `desde Claude Code · ${it.fuente.etiqueta}` : 'desde Claude Code') : 'desde WhatsApp';
      let lab = it.proyecto ? byName.get(String(it.proyecto).trim().toLowerCase()) : undefined;
      if (it.proyecto && !lab) {
        const nombre = String(it.proyecto).trim().slice(0, 60);
        const lid = 'wa' + uid();
        lab = { id: lid, pid: `P${labels.length + nuevos.length + 1}`, emoji: '📁', name: nombre, color: '#2F6FED', score: 50, detalle: '', fuente, historial: [{ id: 'wal' + lid, ts: Number(it.ts) || Date.now(), actor, text: `Creó el proyecto — ${desde}` }] };
        byName.set(nombre.toLowerCase(), lab);
        nuevos.push(lab);
      }
      maxN += 1;
      const rid = String(it.refId || uid());
      return {
        id: rid, num: maxN, emoji: lab?.emoji || '📌', title: String(it.titulo).slice(0, 200),
        detalle: it.detalle ? String(it.detalle) : '', priority: p, score: scoreFromPrio[p], progress: 0,
        deadline: typeof it.deadline === 'string' ? it.deadline : '', labels: lab ? [lab.id] : [], checklist: [],
        enPrioridad: false, origen: actor, fuente,
        historial: [{ id: 'wa' + rid, ts: Number(it.ts) || Date.now(), actor, text: `Creó la tarjeta — ${desde}` }],
      };
    });
  return { tasks, labels: [...labels, ...nuevos] };
}

export function PlanBoard({ user, tareas, proyectos, vacio }: { user: BoardUser; tareas: BoardTask[]; proyectos: Label[]; vacio: boolean }) {
  // El I/O vive en board/repo-plan.ts: lo comparte el roadmap de Customer
  // Success, que abre la MISMA tarjeta con el MISMO modal.
  const repo = repoPlan();
  const board = useBoard(tareas, proyectos, user, repo);
  // DB vacía → el board todavía no se migró de localStorage: mostramos el botón migrar.
  if (vacio) return <MigrarPlan />;
  return <BoardShell board={board} scope="agencia" />;
}

// Migración one-shot (cero consola): lee el board de ESTE navegador (SEED + tus ediciones
// + lo que mergeó la bandeja) y lo SUBE a la DB. Después /plan vive en Supabase
// (multi-dispositivo; MaKo escribe directo). Al terminar recarga y ya corre contra la DB.
function MigrarPlan() {
  const [conteo, setConteo] = useState<{ t: number; p: number } | null>(null);
  const [estado, setEstado] = useState<'idle' | 'yendo' | 'error'>('idle');
  const [err, setErr] = useState('');
  const leerLocal = () => {
    const m = mergeExtras(loadTasks(), loadLabels());
    const fx = fixHistorialDeAltas(m.tasks, m.labels);
    return { tareas: reconcileChecklists(fx.tasks), proyectos: fx.labels };
  };
  useEffect(() => { try { const b = leerLocal(); setConteo({ t: b.tareas.length, p: b.proyectos.length }); } catch { setConteo({ t: 0, p: 0 }); } }, []);
  const migrar = async () => {
    setEstado('yendo');
    try {
      const b = leerLocal();
      const j = await apiPlan({ action: 'migrar', tareas: b.tareas, proyectos: b.proyectos });
      if (!j.ok) throw new Error(j.error || 'falló la migración');
      window.location.reload();
    } catch (e) { setErr(e instanceof Error ? e.message : String(e)); setEstado('error'); }
  };
  return (
    <main style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24, fontFamily: "'Geist', sans-serif" }}>
      <div style={{ maxWidth: 480, textAlign: 'center', background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 18, padding: '32px 28px', boxShadow: '0 8px 30px rgba(20,22,27,.08)' }}>
        <div style={{ fontSize: 34, marginBottom: 6 }}>☁️</div>
        <h1 style={{ fontSize: 22, fontWeight: 700, color: 'var(--ink)', margin: '0 0 8px' }}>Migrá tu Plan a la nube</h1>
        <p style={{ fontSize: 14, color: 'var(--dim)', lineHeight: 1.55, margin: '0 0 16px' }}>
          Tu tablero vivía en <b>este navegador</b>. Lo subimos a la base una sola vez: pasa a ser <b>multi-dispositivo</b> y MaKo lo maneja directo (chau bandeja/snapshot). No perdés nada.
        </p>
        {conteo && <p style={{ fontFamily: "'Geist Mono', monospace", fontSize: 12.5, color: 'var(--faint)', margin: '0 0 18px' }}>{conteo.t} tareas · {conteo.p} proyectos en este navegador</p>}
        <button onClick={migrar} disabled={estado === 'yendo'} style={{ padding: '11px 22px', borderRadius: 10, border: 'none', background: 'var(--ink)', color: 'var(--surface)', fontSize: 14.5, fontWeight: 600, cursor: estado === 'yendo' ? 'default' : 'pointer', opacity: estado === 'yendo' ? 0.6 : 1, fontFamily: 'inherit' }}>
          {estado === 'yendo' ? 'Migrando…' : 'Migrar a la nube'}
        </button>
        {estado === 'error' && <p style={{ fontSize: 12.5, color: 'var(--bad)', marginTop: 14 }}>Error: {err}. Reintentá o avisá a soporte.</p>}
      </div>
    </main>
  );
}
